insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('muhammad','person','النبي محمد ﷺ','pre','570 – 632م',570,'خاتم الأنبياء والمرسلين، محمد بن عبد الله بن عبد المطلب الهاشمي القرشي.','وُلد في مكة عام الفيل ونشأ يتيمًا، وعُرف في قومه بالصادق الأمين. بُعث في الأربعين من عمره، ودعا إلى التوحيد ثلاثة وعشرين عامًا، ثم توفي في المدينة المنورة.','عاش في بيئة قبلية في الجزيرة العربية تسودها عبادة الأصنام، فجاءت رسالته بالتوحيد وبناء مجتمع جديد قائم على العدل والأخوّة.','[["السيرة النبوية — ابن هشام","الجزء الأول والثاني"],["صحيح البخاري","كتاب المناقب"],["الرحيق المختوم — المباركفوري","مواضع متفرقة"]]'::jsonb,array['khadija','abubakr','umar','uthman','ali','aisha','bilal','hamza','abutalib','makkah','madinah','hijra','badr','uhud','hudaybiyyah','fath','companions','birth','revelation','death']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('companions','group','الصحابة','mecca','610 – 632م',610,'الذين لقوا النبي ﷺ مؤمنين به ومات على ذلك.','تعريف الصحابي عند جمهور المحدّثين: من لقي النبي ﷺ مؤمنًا به ومات على الإسلام. وقد حملوا الرسالة ونقلوا السنة وأسسوا الدولة بعده.','تتنوع طبقاتهم: السابقون الأولون، ومهاجرو الحبشة، وأهل بدر، وأصحاب بيعة الرضوان، ومن أسلم عام الفتح.','[["الطبقات الكبرى — ابن سعد","مقدمة الطبقات"],["الإصابة في تمييز الصحابة — ابن حجر","المقدمة"]]'::jsonb,array['abubakr','umar','uthman','ali','bilal','hamza','aisha','musab','salman','khalid','abdurrahman','khadija']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('makkah','place','مكة المكرمة','pre','مولد النبي ﷺ ونشأته',570,'مسقط رأس النبي ﷺ وموطن الوحي ومقر الكعبة المشرفة.','مدينة في وادٍ غير ذي زرع بالحجاز، تضم البيت الحرام، وكانت مركزًا تجاريًا ودينيًا تقوده قريش.','قضى فيها النبي ﷺ ثلاثة وخمسين عامًا قبل الهجرة، وفتحها عام 8هـ.','[["السيرة النبوية — ابن هشام","ذكر بناء الكعبة"],["القرآن الكريم","سورة البلد"]]'::jsonb,array['kaaba','hira','birth','revelation','fath','hijra','khadija','abutalib']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('madinah','place','المدينة المنورة','medina','من 622م',622,'دار الهجرة وعاصمة الدولة الإسلامية الأولى ومدفن النبي ﷺ.','كانت تسمى يثرب، سكنها الأوس والخزرج وقبائل يهودية. غيّر النبي ﷺ اسمها إلى طيبة والمدينة بعد الهجرة.','فيها المسجد النبوي، وانطلقت منها الغزوات وبُني فيها المجتمع المسلم.','[["السيرة النبوية — ابن هشام","ذكر الهجرة"],["صحيح البخاري","كتاب فضائل المدينة"]]'::jsonb,array['hijra','madina_state','badr','uhud','khandaq','death','bilal']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('hira','place','غار حراء','pre','جبل النور – مكة',610,'الغار الذي كان يتعبد فيه النبي ﷺ ونزل فيه أول الوحي.','غار صغير في جبل النور على بعد نحو ثلاثة أميال من مكة، كان النبي ﷺ يتحنث فيه الليالي ذوات العدد.','نزلت فيه أول آيات سورة العلق.','[["صحيح البخاري","كتاب بدء الوحي"]]'::jsonb,array['revelation','makkah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('kaaba','place','الكعبة المشرفة','pre','قبلة المسلمين',605,'البيت الحرام الذي رفع قواعده إبراهيم وإسماعيل عليهما السلام.','أعادت قريش بناءها قبل البعثة بنحو خمس سنوات، وشارك النبي ﷺ في ذلك وحكم في وضع الحجر الأسود.','طهّرها النبي ﷺ من الأصنام يوم فتح مكة.','[["السيرة النبوية — ابن هشام","ذكر بنيان قريش الكعبة"],["القرآن الكريم","سورة البقرة: 127"]]'::jsonb,array['makkah','fath']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('taif','place','الطائف','mecca','السنة العاشرة من البعثة',619,'المدينة التي خرج إليها النبي ﷺ يدعو أهلها فردّوه.','خرج إليها النبي ﷺ ومعه زيد بن حارثة بعد وفاة أبي طالب وخديجة، فآذاه سفهاؤها ورموه بالحجارة.','ورد في الصحيح أن جبريل عرض عليه أن يُطبق عليهم الأخشبين فقال: «بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده».','[["صحيح البخاري","كتاب بدء الخلق"],["صحيح مسلم","كتاب الجهاد والسير"]]'::jsonb,array['abutalib','khadija']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('habasha','place','الحبشة','mecca','هجرتان بين 615 و616م',615,'أرض هاجر إليها المسلمون الأوائل في كنف النجاشي العادل.','قال النبي ﷺ للمسلمين: «إن بها ملكًا لا يُظلم عنده أحد». وأقاموا فيها آمنين على دينهم.','من أبرز من هاجر إليها عثمان بن عفان وزوجته رقية وجعفر بن أبي طالب.','[["السيرة النبوية — ابن هشام","ذكر الهجرة إلى أرض الحبشة"]]'::jsonb,array['najashi','habasha_hijra','uthman']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('elephant','event','عام الفيل','pre','نحو 570م',569.9,'محاولة أبرهة الحبشي هدم الكعبة وهلاك جيشه.','قاد أبرهة جيشًا فيه الفيلة إلى مكة، فأرسل الله عليه طيرًا أبابيل. وفي هذا العام وُلد النبي ﷺ.','ذكرته سورة الفيل، وكان العرب يؤرخون به.','[["القرآن الكريم","سورة الفيل"],["السيرة النبوية — ابن هشام","ذكر أصحاب الفيل"]]'::jsonb,array['kaaba','makkah','birth']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('birth','event','مولد النبي ﷺ','pre','12 ربيع الأول – عام الفيل',570,'ولادة محمد بن عبد الله يتيمًا في مكة.','وُلد بعد وفاة أبيه عبد الله، وكفله جده عبد المطلب ثم عمه أبو طالب. استرضع في بني سعد عند حليمة السعدية.','المتفق عليه أنه وُلد يوم الاثنين في عام الفيل.','[["السيرة النبوية — ابن هشام","ذكر مولد رسول الله ﷺ"],["صحيح مسلم","كتاب الصيام – صوم يوم الاثنين"]]'::jsonb,array['muhammad','elephant','makkah','abutalib']::text[],'يوم الشهر مختلف فيه: فالمشهور 12 ربيع الأول، وقيل 2 أو 8 أو 9. والمعتمد عند الفلكيين المعاصرين 9 ربيع الأول.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('marriage','event','الزواج من خديجة','pre','نحو 595م',595,'زواج النبي ﷺ من خديجة بنت خويلد وهو في الخامسة والعشرين.','عمل النبي ﷺ في تجارتها إلى الشام فرأت أمانته، فعرضت عليه الزواج. وأنجبت له أولاده عدا إبراهيم.','كانت أول من آمن به وسنده في أصعب سنوات الدعوة.','[["السيرة النبوية — ابن هشام","حديث تزويج خديجة"],["الطبقات الكبرى — ابن سعد","ترجمة خديجة"]]'::jsonb,array['khadija','muhammad']::text[],'عمر خديجة عند الزواج: المشهور أربعون، وقيل غير ذلك.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('revelation','event','نزول الوحي','mecca','رمضان – نحو 610م',610,'نزول جبريل بأول آيات القرآن في غار حراء: ﴿اقرأ باسم ربك الذي خلق﴾.','جاء النبي ﷺ وهو في الأربعين فضمّه جبريل وقال له: اقرأ، فرجع إلى خديجة يرجف فؤاده فطمأنته وانطلقت به إلى ورقة بن نوفل.','ثم فتر الوحي مدة ونزلت سورة المدثر بالأمر بالإنذار.','[["صحيح البخاري","كتاب بدء الوحي، باب كيف كان بدء الوحي"],["القرآن الكريم","سورة العلق"]]'::jsonb,array['hira','khadija','makkah','muhammad','dawah']::text[],'تحديد يوم النزول في رمضان مختلف فيه (17 أو 21 أو 24)، والأرجح عند كثيرين ليلة القدر.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('dawah','event','الجهر بالدعوة','mecca','نحو 613م',613,'بعد ثلاث سنوات من الدعوة السرية أمر الله نبيه بإعلان الدعوة.','صعد النبي ﷺ جبل الصفا ونادى قريشًا، ونزل قوله تعالى ﴿وأنذر عشيرتك الأقربين﴾.','اشتد بعدها إيذاء المشركين للمسلمين.','[["صحيح البخاري","تفسير سورة المسد"],["السيرة النبوية — ابن هشام","ذكر الجهر بالدعوة"]]'::jsonb,array['abubakr','bilal','abutalib','makkah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('habasha_hijra','event','الهجرة إلى الحبشة','mecca','السنة الخامسة من البعثة',615,'فرار المسلمين بدينهم من أذى قريش إلى النجاشي.','خرجت الفوج الأول نحو اثني عشر رجلًا وأربع نسوة، ثم تبعتهم جموع أكبر. وأرسلت قريش وفدًا إلى النجاشي فردّهم.','حفظت كتب السير حوار جعفر بن أبي طالب مع النجاشي.','[["السيرة النبوية — ابن هشام","ذكر الهجرة إلى الحبشة"],["البداية والنهاية — ابن كثير","الهجرة الأولى"]]'::jsonb,array['habasha','najashi','uthman']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('sorrow','event','عام الحزن','mecca','السنة العاشرة من البعثة – 619م',619,'وفاة أبي طالب ثم خديجة، وخروج النبي ﷺ إلى الطائف.','فقد النبي ﷺ حاميه وزوجه في فترة وجيزة، فاشتد أذى قريش عليه.','سُمي بذلك عند أهل السير.','[["السيرة النبوية — ابن هشام","وفاة أبي طالب وخديجة"],["البداية والنهاية — ابن كثير","عام الحزن"]]'::jsonb,array['abutalib','khadija','taif']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('isra','event','الإسراء والمعراج','mecca','قبل الهجرة',620,'رحلة النبي ﷺ ليلًا من المسجد الحرام إلى الأقصى ثم العروج إلى السماوات.','فرضت فيها الصلوات الخمس، ورأى النبي ﷺ من آيات ربه الكبرى.','ذكرها القرآن في أول سورة الإسراء وسورة النجم.','[["القرآن الكريم","سورة الإسراء: 1"],["صحيح البخاري","كتاب مناقب الأنصار – باب المعراج"]]'::jsonb,array['makkah']::text[],'ثبوت الرحلة قطعي، أما تاريخها فمختلف فيه، وليلة 27 رجب المشهورة لا يصح فيها دليل.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('aqaba','event','بيعتا العقبة','mecca','621 – 622م',621.5,'بايع وفد الأنصار النبي ﷺ على نصرته ومنعه كما يمنعون نساءهم وأبناءهم.','في العقبة الأولى بايع اثنا عشر، وفي الثانية بايع ثلاثة وسبعون رجلًا وامرأتان. وأرسل النبي ﷺ مصعب بن عمير معلمًا.','مهّدت مباشرة للهجرة إلى المدينة.','[["السيرة النبوية — ابن هشام","ذكر بيعة العقبة الأولى والثانية"]]'::jsonb,array['musab','madinah','hijra']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('hijra','event','الهجرة إلى المدينة','hijra','1هـ – 622م',622,'انتقال النبي ﷺ مع أبي بكر من مكة إلى المدينة وبداية التقويم الهجري.','خرجا ليلًا واختبآ في غار ثور ثلاثة أيام، ثم سارا بصحبة دليل إلى قباء فالمدينة. وقد استقبله أهلها بالفرح.','أُرِّخ بها في عهد عمر بن الخطاب رضي الله عنه.','[["صحيح البخاري","كتاب مناقب الأنصار – باب هجرة النبي ﷺ"],["السيرة النبوية — ابن هشام","ذكر الهجرة"]]'::jsonb,array['abubakr','ali','makkah','madinah','madina_state']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('madina_state','event','بناء الدولة الإسلامية','medina','1هـ – 622 / 623م',622.5,'بناء المسجد النبوي والمؤاخاة بين المهاجرين والأنصار وكتابة وثيقة المدينة.','بدأ النبي ﷺ ببناء المسجد، ثم آخى بين المهاجرين والأنصار، ونظّم العلاقة بين سكان المدينة بوثيقة عُرفت بصحيفة المدينة.','شكلت هذه الخطوات نواة المجتمع والدولة.','[["السيرة النبوية — ابن هشام","ذكر بناء المسجد والمؤاخاة والصحيفة"],["صحيح البخاري","كتاب مناقب الأنصار – المؤاخاة"]]'::jsonb,array['madinah','abdurrahman','bilal']::text[],'أصل الصحيفة مروي عند ابن إسحاق وغيره، لكن ألفاظها وجمعها في وثيقة واحدة محل نقاش بين الباحثين.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('badr','event','غزوة بدر الكبرى','medina','17 رمضان 2هـ – 624م',624,'أول معركة فاصلة بين المسلمين وقريش وانتصار المسلمين فيها.','خرج النبي ﷺ في نحو ثلاثمئة وثلاثة عشر رجلًا فواجهوا نحو ألف من قريش، ونصرهم الله على قلة العدد والعدة.','سماها القرآن يوم الفرقان.','[["القرآن الكريم","سورة الأنفال"],["صحيح البخاري","كتاب المغازي – غزوة بدر"]]'::jsonb,array['hamza','ali','bilal','madinah','abubakr','umar']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('uhud','event','غزوة أحد','medina','شوال 3هـ – 625م',625,'معركة عند جبل أحد استُشهد فيها حمزة وعدد من الصحابة.','بدأت بنصر المسلمين، ثم خالف الرماة أمر النبي ﷺ فالتفّ خالد بن الوليد بفرسان قريش.','تحدثت عنها سورة آل عمران.','[["القرآن الكريم","سورة آل عمران: 121–179"],["صحيح البخاري","كتاب المغازي – غزوة أحد"]]'::jsonb,array['hamza','khalid','musab','madinah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('khandaq','event','غزوة الخندق','medina','شوال 5هـ – 627م',627,'تحالف الأحزاب لحصار المدينة، وحفر الخندق بمشورة سلمان الفارسي.','حاصرت الأحزاب المدينة نحو شهر، فأرسل الله عليهم ريحًا وجنودًا فانصرفوا خائبين.','نزلت فيها آيات سورة الأحزاب.','[["القرآن الكريم","سورة الأحزاب"],["السيرة النبوية — ابن هشام","غزوة الخندق"]]'::jsonb,array['salman','madinah']::text[],'تختلف الروايات في سنة الغزوة: المشهور 5هـ، وقيل 4هـ.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('hudaybiyyah','event','صلح الحديبية','medina','ذو القعدة 6هـ – 628م',628,'صلح بين النبي ﷺ وقريش على وقف الحرب عشر سنين.','خرج النبي ﷺ معتمرًا فمنعته قريش، فتصالحوا على العودة العام المقبل. وبدا الصلح لبعض الصحابة ثقيلًا لكن الله سماه فتحًا.','تبعته بيعة الرضوان تحت الشجرة.','[["القرآن الكريم","سورة الفتح"],["صحيح البخاري","كتاب الشروط – الشروط في الجهاد"]]'::jsonb,array['umar','uthman','abubakr','ali','makkah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('fath','event','فتح مكة','medina','رمضان 8هـ – 630م',630,'دخول النبي ﷺ مكة في عشرة آلاف من أصحابه وتطهير الكعبة من الأصنام.','نقضت قريش الصلح فسار إليها النبي ﷺ، ودخلها متواضعًا وعفا عن أهلها فقال: «اذهبوا فأنتم الطلقاء».','دخل الناس بعده في دين الله أفواجًا.','[["القرآن الكريم","سورة النصر"],["صحيح البخاري","كتاب المغازي – فتح مكة"]]'::jsonb,array['makkah','kaaba','khalid','bilal','abubakr']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('farewell','event','حجة الوداع','medina','10هـ – 632م',631.8,'الحجة الوحيدة للنبي ﷺ وفيها خطبة عرفة الجامعة.','خطب بعرفة مقررًا حرمة الدماء والأموال وحقوق النساء، ونزل قوله تعالى ﴿اليوم أكملت لكم دينكم﴾.','كان معه أكثر من مئة ألف من الصحابة.','[["صحيح مسلم","كتاب الحج – حجة النبي ﷺ"],["القرآن الكريم","سورة المائدة: 3"]]'::jsonb,array['makkah','ali','abubakr']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('death','event','وفاة النبي ﷺ','medina','ربيع الأول 11هـ – 632م',632,'انتقال النبي ﷺ إلى الرفيق الأعلى في المدينة وعمره ثلاث وستون سنة.','مرض أيامًا وأمر أبا بكر أن يصلي بالناس، وتوفي في بيت عائشة رضي الله عنها ودُفن فيه.','تولى أبو بكر الخلافة بعده.','[["صحيح البخاري","كتاب المغازي – باب مرض النبي ﷺ ووفاته"],["السيرة النبوية — ابن هشام","ذكر وفاة رسول الله ﷺ"]]'::jsonb,array['aisha','abubakr','madinah','muhammad']::text[],'الأشهر أنه توفي يوم الاثنين 12 ربيع الأول، وقيل 2 ربيع الأول.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('khadija','person','خديجة بنت خويلد','pre','ت. 619م',595,'أم المؤمنين الأولى وأول من آمن بالنبي ﷺ.','تاجرة قرشية ذات مال وشرف، تزوجها النبي ﷺ ولم يتزوج عليها حتى ماتت. دعمت الدعوة بمالها ونفسها.','توفيت قبل الهجرة بثلاث سنين، وكان النبي ﷺ يذكرها بالوفاء.','[["صحيح البخاري","كتاب مناقب الأنصار – تزويج النبي ﷺ خديجة"],["الطبقات الكبرى — ابن سعد","ترجمة خديجة"]]'::jsonb,array['marriage','revelation','sorrow']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('abubakr','person','أبو بكر الصديق','mecca','ت. 13هـ',611,'صاحب النبي ﷺ في الغار وأول الخلفاء الراشدين.','عبد الله بن أبي قحافة التيمي، أول الرجال إسلامًا في الرواية المشهورة، أعتق المستضعفين ورافق النبي ﷺ في الهجرة. تولى الخلافة بعد وفاته ﷺ.','حارب المرتدين وجمع القرآن في صحف بمشورة عمر.','[["صحيح البخاري","كتاب فضائل الصحابة"],["الطبقات الكبرى — ابن سعد","ترجمة أبي بكر"]]'::jsonb,array['hijra','bilal','death','dawah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('umar','person','عمر بن الخطاب','mecca','ت. 23هـ',616,'الفاروق وثاني الخلفاء الراشدين، أسلم فعزّ الإسلام.','من بني عدي، اشتهر بالشدة في الحق والعدل. أسلم في مكة وشهد المشاهد كلها، وتولى الخلافة عشر سنين فُتحت فيها الشام والعراق ومصر.','وضع التقويم الهجري ودوّن الدواوين.','[["صحيح البخاري","كتاب فضائل الصحابة"],["البداية والنهاية — ابن كثير","خلافة عمر"]]'::jsonb,array['hudaybiyyah','badr']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('uthman','person','عثمان بن عفان','mecca','ت. 35هـ',614,'ذو النورين وثالث الخلفاء الراشدين.','تزوج ابنتي النبي ﷺ رقية ثم أم كلثوم. هاجر إلى الحبشة ثم المدينة، وجهّز جيش العسرة، وجمع المصاحف على مصحف واحد.','استُشهد في الفتنة سنة 35هـ.','[["صحيح البخاري","كتاب فضائل الصحابة"],["الطبقات الكبرى — ابن سعد","ترجمة عثمان"]]'::jsonb,array['habasha_hijra','hudaybiyyah']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('ali','person','علي بن أبي طالب','mecca','ت. 40هـ',611,'ابن عم النبي ﷺ وزوج فاطمة ورابع الخلفاء الراشدين.','نشأ في بيت النبي ﷺ وأسلم صغيرًا. نام في فراشه ليلة الهجرة وردّ الأمانات، وشهد المشاهد إلا تبوك.','اشتهر بالعلم والشجاعة والقضاء.','[["صحيح البخاري","كتاب فضائل الصحابة"],["السيرة النبوية — ابن هشام","مبيت علي على فراش النبي"]]'::jsonb,array['hijra','badr','abutalib']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('aisha','person','عائشة بنت أبي بكر','hijra','ت. 58هـ',623,'أم المؤمنين، من أكثر الصحابة رواية وفقهًا.','تزوجها النبي ﷺ بمكة وبنى بها بالمدينة. روت أكثر من ألفي حديث، وكان كبار الصحابة يسألونها.','توفي النبي ﷺ في بيتها ودُفن فيه.','[["الطبقات الكبرى — ابن سعد","ترجمة عائشة"],["صحيح البخاري","كتاب فضائل الصحابة"]]'::jsonb,array['death','abubakr']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('bilal','person','بلال بن رباح','mecca','ت. نحو 20هـ',613,'أول مؤذن في الإسلام وصاحب الثبات تحت التعذيب.','عبد حبشي لأمية بن خلف عُذّب على إسلامه فقال «أحدٌ أحد»، فاشتراه أبو بكر وأعتقه.','أذّن يوم فتح مكة فوق الكعبة.','[["السيرة النبوية — ابن هشام","ذكر تعذيب بلال"],["صحيح البخاري","كتاب مناقب الأنصار"]]'::jsonb,array['abubakr','fath','madina_state']::text[],'سنة وفاته ومكانها مختلف فيها بين السير (دمشق أو حلب).',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('hamza','person','حمزة بن عبد المطلب','mecca','ت. 3هـ',615,'عم النبي ﷺ وأسد الله، سيد الشهداء.','أسلم في السنة الثانية من البعثة وعزّ به المسلمون. أبلى في بدر ثم استشهد يوم أحد.','قتله وحشي بن حرب بأمر هند بنت عتبة.','[["صحيح البخاري","كتاب المغازي – قتل حمزة"],["السيرة النبوية — ابن هشام","غزوة أحد"]]'::jsonb,array['badr','uhud']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('abutalib','person','أبو طالب بن عبد المطلب','pre','ت. 619م',580,'عم النبي ﷺ وكافله وحاميه من قريش.','كفل النبي ﷺ بعد جده، وحماه من أذى قريش عشر سنين بعد البعثة، لكنه مات على دين قومه.','ورد في الصحيحين أنه لم ينطق الشهادة عند موته.','[["صحيح البخاري","كتاب مناقب الأنصار – قصة أبي طالب"],["السيرة النبوية — ابن هشام","وفاة أبي طالب"]]'::jsonb,array['sorrow','ali']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('najashi','person','النجاشي أصحمة','mecca','ت. 9هـ',615,'ملك الحبشة العادل الذي آوى المهاجرين.','استمع إلى سورة مريم من جعفر بن أبي طالب فبكى ورفض تسليم المسلمين لقريش، وأسلم.','صلى عليه النبي ﷺ صلاة الغائب عند موته.','[["صحيح البخاري","كتاب الجنائز – الصلاة على النجاشي"],["السيرة النبوية — ابن هشام","ذكر الهجرة إلى الحبشة"]]'::jsonb,array['habasha','habasha_hijra']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('musab','person','مصعب بن عمير','mecca','ت. 3هـ',621,'أول سفير في الإسلام، أرسله النبي ﷺ يعلّم أهل المدينة.','شاب مترف من مكة ترك النعيم لدينه. أسلم على يده كثير من الأنصار منهم أسيد بن حضير وسعد بن معاذ.','حمل لواء المسلمين يوم أحد واستشهد.','[["صحيح البخاري","كتاب المغازي – غزوة أحد"],["السيرة النبوية — ابن هشام","ذكر مصعب"]]'::jsonb,array['aqaba','uhud']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('salman','person','سلمان الفارسي','hijra','ت. نحو 35هـ',622,'الباحث عن الحق من فارس، ومشير الخندق.','رحل من بلاد فارس طالبًا الحق حتى وصل المدينة فأسلم. أشار بحفر الخندق.','قال النبي ﷺ: «سلمان منا أهل البيت».','[["السيرة النبوية — ابن هشام","خبر سلمان"],["الطبقات الكبرى — ابن سعد","ترجمة سلمان"]]'::jsonb,array['khandaq']::text[],'عمره عند وفاته مختلف فيه جدًا بين الروايات.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('khalid','person','خالد بن الوليد','medina','ت. 21هـ',628,'سيف الله المسلول، القائد العسكري العظيم.','من فرسان قريش وقاد التفاف أحد، ثم أسلم قبل الفتح وشهد مؤتة وقاد الجيوش بعد النبي ﷺ.','سماه النبي ﷺ سيف الله.','[["صحيح البخاري","كتاب المغازي – غزوة مؤتة"],["البداية والنهاية — ابن كثير","ترجمة خالد"]]'::jsonb,array['uhud','fath']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('abdurrahman','person','عبد الرحمن بن عوف','mecca','ت. 32هـ',614,'من العشرة المبشرين بالجنة، وتاجر الصحابة الأمين.','هاجر الهجرتين، وآخى النبي ﷺ بينه وبين سعد بن الربيع فرفض مال أخيه وقال: دلّوني على السوق.','تصدق بثروة كبيرة في سبيل الله.','[["صحيح البخاري","كتاب مناقب الأنصار – المؤاخاة"]]'::jsonb,array['madina_state']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('arabia_pre','event','الجزيرة العربية قبل مولد النبي ﷺ','pre','قبل 570م',560,'المجتمع القبلي في الجزيرة العربية ومكانة قريش ومكة قبل مولد النبي ﷺ.','كانت الحياة في الجزيرة العربية قائمة على القبيلة والتجارة والقوافل، وكانت قريش تتولى شؤون البيت الحرام في مكة، وانتشرت عبادة الأصنام حول الكعبة. وعاش في بعض أطراف الجزيرة وبلداتها يهود ونصارى، ووُجد من العرب من تبرّأ من عبادة الأصنام ويُعرفون بالحنفاء.','ذكرت سورة قريش رحلة الشتاء والصيف التي اشتهرت بها قريش.','[["السيرة النبوية — ابن هشام","ذكر عمرو بن لحي وعبادة الأصنام"],["القرآن الكريم","سورة قريش"]]'::jsonb,array['makkah','kaaba','elephant']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('childhood','event','طفولته ﷺ ويُتمه','pre','570 – نحو 578م',575,'نشأة النبي ﷺ يتيمًا بين الرضاعة في بني سعد وكفالة جده ثم عمه.','استُرضع في بني سعد عند حليمة السعدية، ثم عاد إلى أمه آمنة التي توفيت في طريق عودتها من المدينة بالأبواء وهو في نحو السادسة، فكفله جده عبد المطلب، ثم عمه أبو طالب.','تذكر كتب السير أن عمره عند وفاة جده كان نحو ثماني سنين.','[["السيرة النبوية — ابن هشام","ذكر رضاعه ﷺ في بني سعد"],["السيرة النبوية — ابن هشام","ذكر وفاة آمنة وكفالة عبد المطلب وأبي طالب"]]'::jsonb,array['birth','abutalib','makkah']::text[],'تختلف الروايات في عمره عند وفاة أمه وجده، وفي ترتيب بعض الأحداث.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('youth','event','شبابه ﷺ وأمانته','pre','نحو 580 – 595م',588,'رعيه الغنم وسفره بالتجارة وسمعته بالصدق والأمانة قبل البعثة.','عمل ﷺ في رعي الغنم لأهل مكة، وخرج بالتجارة، واشتهر بين قومه بالصادق الأمين، وشهد حلف الفضول مع أعمامه.','تذكر بعض كتب السير رحلته إلى الشام مع عمه أبي طالب وهو صغير، ولقاءه بالراهب بحيرى.','[["صحيح البخاري","كتاب الإجارة، باب رعي الغنم على قراريط"],["السيرة النبوية — ابن هشام","ذكر حلف الفضول"]]'::jsonb,array['abutalib','khadija','marriage','makkah']::text[],'تختلف الروايات في تفاصيل رحلة الشام وفي ثبوت قصة بحيرى، وفي سنّه عند حلف الفضول.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('kaaba_rebuild','event','بناء قريش للكعبة وتحكيم النبي ﷺ','pre','نحو 605م (قبل البعثة بنحو خمس سنين)',605,'تجديد قريش بناء الكعبة، وتحكيمهم النبي ﷺ في موضع الحجر الأسود.','اختلفت قبائل قريش فيمن يضع الحجر الأسود، فاتفقوا على تحكيم أول داخل عليهم، فكان النبي ﷺ، فوضع الحجر في ثوب وحملته القبائل جميعًا ثم وضعه بيده.','كان النبي ﷺ في نحو الخامسة والثلاثين في روايات السير.','[["السيرة النبوية — ابن هشام","ذكر بنيان قريش الكعبة"]]'::jsonb,array['kaaba','makkah','marriage']::text[],'تختلف الروايات في سنّه ﷺ عند بناء الكعبة، والمشهور أنه نحو خمس وثلاثين سنة.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('secret_dawah','event','الدعوة السرية','mecca','نحو 610 – 613م',610.5,'السنوات الأولى للدعوة سرًّا بين الأقربين والمقرّبين قبل الجهر بها.','دعا النبي ﷺ سرًّا من يثق بهم، فآمن به خديجة وأبو بكر وعلي وزيد بن حارثة ومن تبعهم، وكان المسلمون يخفون عبادتهم.','ذكرت السير أن دار الأرقم بن أبي الأرقم كانت من مواضع اجتماع المسلمين.','[["السيرة النبوية — ابن هشام","ذكر ابتداء الدعوة والسابقين إلى الإسلام"]]'::jsonb,array['khadija','abubakr','ali','revelation','dawah','makkah']::text[],'المشهور أن المرحلة السرية استمرت نحو ثلاث سنوات، وتختلف الروايات في مدتها.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('persecution','event','اضطهاد المسلمين الأوائل','mecca','من نحو 613م',613.5,'الأذى الذي لقيه النبي ﷺ والمستضعفون من المسلمين بعد الجهر بالدعوة.','تعرّض كثير من المسلمين المستضعفين للتعذيب والأذى، ومنهم بلال بن رباح، واشترى أبو بكر عددًا منهم فأعتقهم، وتعرّض النبي ﷺ نفسه للأذى والسخرية.','دفعت هذه المحنة بعض المسلمين إلى الهجرة إلى الحبشة.','[["السيرة النبوية — ابن هشام","ذكر ما لقي المسلمون من الأذى"]]'::jsonb,array['bilal','abubakr','dawah','habasha_hijra','abutalib']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('boycott','event','حصار شعب أبي طالب','mecca','نحو 616 – 619م (من السنة السابعة إلى العاشرة للبعثة)',616.5,'مقاطعة قريش لبني هاشم وبني المطلب وحصارهم في الشعب.','تعاقدت قريش على مقاطعة بني هاشم وبني المطلب في البيع والزواج، فاحتمى النبي ﷺ ومن معه في شعب أبي طالب مدة، ثم نُقضت الصحيفة.','جاء بعدها عام الحزن.','[["السيرة النبوية — ابن هشام","ذكر الصحيفة وحصار الشعب"],["البداية والنهاية — ابن كثير","حصار بني هاشم في الشعب"]]'::jsonb,array['abutalib','khadija','sorrow','makkah']::text[],'تختلف الروايات في تاريخ بدايتها ومدتها: المشهور نحو ثلاث سنين، وقيل أقل.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('taif_trip','event','رحلة الطائف','mecca','شوال، السنة العاشرة من البعثة – نحو 619م',619.5,'خروج النبي ﷺ إلى الطائف يدعو أهلها بعد وفاة أبي طالب وخديجة.','خرج ومعه زيد بن حارثة فعرض الإسلام على سادة ثقيف فردّوه وأغروا به سفهاءهم فرموه بالحجارة، ثم عاد إلى مكة في جوار المطعم بن عدي.','وردت في الصحيح رواية عائشة رضي الله عنها عن أشد ما لقي النبي ﷺ يوم الطائف.','[["صحيح البخاري","كتاب بدء الخلق"],["السيرة النبوية — ابن هشام","ذكر خروجه إلى الطائف"]]'::jsonb,array['taif','sorrow','abutalib','khadija']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('khaybar','event','غزوة خيبر','medina','محرم 7هـ – 628م',628.4,'حملة المسلمين على حصون يهود خيبر شمال المدينة بعد صلح الحديبية.','سار النبي ﷺ إلى خيبر بعد عودته من الحديبية فحاصر حصونها وفتحها، وأقرّ أهلها على العمل في الأرض بنصف الثمر.','ورد في الصحيح أن النبي ﷺ أعطى الراية لعلي بن أبي طالب في هذه الغزوة.','[["صحيح البخاري","كتاب المغازي، باب غزوة خيبر"],["السيرة النبوية — ابن هشام","ذكر غزوة خيبر"]]'::jsonb,array['hudaybiyyah','ali','madinah']::text[],'تختلف الروايات في شهر الغزوة: المشهور محرم من السنة السابعة، وقيل غير ذلك.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('muta','event','غزوة مؤتة','medina','جمادى الأولى 8هـ – 629م',629.7,'معركة بين المسلمين وجيش الروم وحلفائهم في أطراف الشام استُشهد فيها ثلاثة من قادة المسلمين.','بعث النبي ﷺ جيشًا بقيادة زيد بن حارثة ثم جعفر بن أبي طالب ثم عبد الله بن رواحة، فاستُشهدوا، فأخذ الراية خالد بن الوليد وعاد بالجيش.','ورد في رواية البخاري أن النبي ﷺ سمّى خالدًا سيفًا من سيوف الله عند هذه الواقعة.','[["صحيح البخاري","كتاب المغازي، باب غزوة مؤتة من أرض الشام"],["السيرة النبوية — ابن هشام","ذكر غزوة مؤتة"]]'::jsonb,array['khalid','madinah']::text[],'تتفاوت الروايات في تقدير عدد الجيشين وفي وصف نتيجة اللقاء.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('hunayn','event','غزوة حنين','medina','شوال 8هـ – 630م',630.1,'معركة المسلمين مع هوازن وثقيف بعد فتح مكة.','خرج المسلمون في جيش كبير، فباغتهم العدو في وادي حنين فاضطربت صفوفهم، ثم ثبت النبي ﷺ ومن معه وعاد المسلمون فانتصروا.','أشار القرآن إلى هذا اليوم في سورة التوبة، ثم توجه المسلمون إلى الطائف.','[["صحيح البخاري","كتاب المغازي، باب قول الله تعالى: ويوم حنين"],["القرآن الكريم","سورة التوبة: 25–26"],["السيرة النبوية — ابن هشام","ذكر غزوة حنين"]]'::jsonb,array['fath','makkah','taif']::text[],null,null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('tabuk','event','غزوة تبوك','medina','رجب 9هـ – 630م',630.8,'خروج النبي ﷺ بجيش كبير نحو تبوك في أطراف الشام ولم يقع قتال.','خرج النبي ﷺ في زمن شدة وحرّ لمواجهة ما بلغه من حشود الروم، ووصل تبوك وأقام فيها أيامًا ثم عاد دون قتال، وسُمّي جيشه جيش العسرة.','تخلّف عنه ثلاثة من الصحابة ثم تاب الله عليهم.','[["صحيح البخاري","كتاب المغازي، باب غزوة تبوك"],["القرآن الكريم","سورة التوبة: 117–118"]]'::jsonb,array['uthman','madinah']::text[],'تتفاوت الروايات في مدة إقامته بتبوك.',null) on conflict (id) do nothing;
insert into entities (id,kind,name,period,"when",y,summary,bio,context,sources,rel,disputed,kw) values ('illness','event','مرض النبي ﷺ الأخير','medina','أواخر صفر – ربيع الأول 11هـ – 632م',631.9,'أيام مرض النبي ﷺ الأخيرة في بيت عائشة حتى وفاته.','اشتد به المرض فاستأذن أزواجه أن يُمرَّض في بيت عائشة فأذنّ له، وأمر أبا بكر أن يصلي بالناس.','سبق مرضَه تجهيزُ جيش أسامة بن زيد.','[["صحيح البخاري","كتاب المغازي، باب مرض النبي ﷺ ووفاته"],["صحيح البخاري","كتاب الأذان، باب أهل العلم والفضل أحق بالإمامة"]]'::jsonb,array['aisha','abubakr','death','madinah']::text[],'تختلف الروايات في بداية المرض ومدته: المشهور نحو عشرة أيام، وقيل ثلاثة عشر يومًا.',null) on conflict (id) do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muhammad','fr','{"name":"Le Prophète Muhammad ﷺ","when":"570 – 632","summary":"Sceau des prophètes et des messagers, Muhammad ibn ʿAbd Allāh ibn ʿAbd al-Muṭṭalib, des Banū Hāshim, de Quraysh.","bio":"Il naquit à La Mecque l''année de l''Éléphant et grandit orphelin ; parmi les siens, on le connaissait comme le Véridique, le Digne de confiance. Il fut envoyé à l''âge de quarante ans, appela à l''unicité de Dieu pendant vingt-trois ans, puis mourut à Médine al-Munawwara.","context":"Il vécut dans un milieu tribal de la péninsule arabique dominé par l''idolâtrie ; son message apporta le monothéisme et l''édification d''une société nouvelle fondée sur la justice et la fraternité.","sources":[["La Biographie prophétique — Ibn Hishām","Parties 1 et 2"],["Sahih al-Bukhari","Livre des mérites"],["Le Nectar cacheté — al-Mubārakfūrī","Passages divers"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('companions','fr','{"name":"Les Compagnons","when":"610 – 632","summary":"Ceux qui ont rencontré le Prophète ﷺ en croyant en lui et sont morts dans cette foi.","bio":"Définition du Compagnon selon la majorité des spécialistes du hadith : celui qui a rencontré le Prophète ﷺ en croyant en lui et est mort musulman. Ils ont porté le message, transmis la Sunna et fondé l''État après lui.","context":"Ils se répartissent en plusieurs rangs : les premiers croyants, les émigrés en Abyssinie, les combattants de Badr, ceux qui prêtèrent le serment de Ridwān, et ceux qui embrassèrent l''islam l''année de la Conquête.","sources":[["Les Grandes Générations — Ibn Saʿd","Introduction aux Ṭabaqāt"],["al-Iṣāba fī Tamyīz al-Ṣaḥāba — Ibn Ḥajar","Introduction"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('makkah','fr','{"name":"La Mecque (al-Mukarrama)","when":"Naissance et enfance du Prophète ﷺ","summary":"Lieu de naissance du Prophète ﷺ, terre de la révélation et siège de la noble Kaaba.","bio":"Ville située dans une vallée dépourvue de cultures au Hedjaz, abritant la Maison sacrée ; c''était un centre commercial et religieux dirigé par Quraysh.","context":"Le Prophète ﷺ y vécut cinquante-trois ans avant l''Hégire, et la conquit en 8 AH.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la construction de la Kaaba"],["Le Noble Coran","Sourate al-Balad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madinah','fr','{"name":"Médine (al-Munawwara)","when":"À partir de 622","summary":"Ville de l''Hégire, capitale du premier État islamique et lieu de sépulture du Prophète ﷺ.","bio":"Elle s''appelait Yathrib ; y vivaient les Aws, les Khazraj et des tribus juives. Après l''Hégire, le Prophète ﷺ changea son nom en Ṭayba et al-Madīna.","context":"Elle abrite la Mosquée du Prophète ; les expéditions en partirent et la communauté musulmane s''y construisit.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de l''Hégire"],["Sahih al-Bukhari","Livre des vertus de Médine"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hira','fr','{"name":"La grotte de Hira","when":"Jabal al-Nour – La Mecque","summary":"La grotte où le Prophète ﷺ se retirait pour adorer et où descendit la première révélation.","bio":"Petite grotte du Jabal al-Nūr, à environ trois milles de La Mecque, où le Prophète ﷺ se retirait pour l''adoration durant un certain nombre de nuits.","context":"Les premiers versets de la sourate al-ʿAlaq y furent révélés.","sources":[["Sahih al-Bukhari","Livre du commencement de la révélation"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba','fr','{"name":"La noble Kaaba","when":"Qibla des musulmans","summary":"La Maison sacrée dont Ibrahim et Ismaïl, paix sur eux, ont élevé les fondations.","bio":"Quraysh la reconstruisit environ cinq ans avant la mission ; le Prophète ﷺ y participa et arbitra la pose de la Pierre noire.","context":"Le Prophète ﷺ la purifia des idoles le jour de la Conquête de La Mecque.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la reconstruction de la Kaaba par Quraysh"],["Le Noble Coran","Sourate al-Baqara 2:127"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif','fr','{"name":"Taïf","when":"10ᵉ année de la mission","summary":"La ville où le Prophète ﷺ se rendit pour appeler ses habitants, qui le repoussèrent.","bio":"Le Prophète ﷺ s''y rendit avec Zayd ibn Ḥāritha après la mort d''Abū Ṭālib et de Khadīja ; ses insensés lui firent du mal et lui jetèrent des pierres.","context":"Il est rapporté dans le Ṣaḥīḥ que Jibrīl lui proposa de refermer sur eux les deux montagnes, et il répondit : « Plutôt, j''espère que Dieu fera sortir de leurs reins ceux qui adoreront Dieu seul. »","sources":[["Sahih al-Bukhari","Livre du commencement de la création"],["Sahih Muslim","Livre du jihad et des expéditions"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha','fr','{"name":"L''Abyssinie","when":"Deux migrations, 615 et 616","summary":"La terre où émigrèrent les premiers musulmans, sous la protection du Négus juste.","bio":"Le Prophète ﷺ dit aux musulmans : « Il y a là-bas un roi auprès de qui nul n''est lésé. » Ils y demeurèrent en sécurité dans leur religion.","context":"Parmi les plus éminents émigrés : ʿUthmān ibn ʿAffān et son épouse Ruqayya, ainsi que Jaʿfar ibn Abī Ṭālib.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de l''émigration en terre d''Abyssinie"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('elephant','fr','{"name":"L''Année de l''Éléphant","when":"vers 570","summary":"La tentative d''Abraha l''Abyssin de détruire la Kaaba et l''anéantissement de son armée.","bio":"Abraha mena vers La Mecque une armée comptant des éléphants, et Dieu envoya contre elle des vols d''oiseaux. Le Prophète ﷺ naquit cette année-là.","context":"La sourate al-Fīl l''évoque, et les Arabes s''en servaient pour dater les événements.","sources":[["Le Noble Coran","Sourate al-Fīl"],["La Biographie prophétique — Ibn Hishām","Récit des gens de l''Éléphant"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('birth','fr','{"name":"Naissance du Prophète ﷺ","when":"12 Rabīʿ al-Awwal – Année de l''Éléphant","summary":"Naissance de Muhammad ibn ʿAbd Allāh à La Mecque, orphelin de père.","disputed":"Le jour du mois est discuté : le plus connu est le 12 Rabīʿ al-Awwal ; on rapporte aussi le 2, le 8 ou le 9. Les astronomes contemporains retiennent le 9 Rabīʿ al-Awwal.","bio":"Il naquit après la mort de son père ʿAbd Allāh ; son grand-père ʿAbd al-Muṭṭalib, puis son oncle Abū Ṭālib, le prirent en charge. Il fut mis en nourrice chez les Banū Saʿd, auprès de Ḥalīma al-Saʿdiyya.","context":"Ce qui est admis, c''est qu''il naquit un lundi, l''année de l''Éléphant.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la naissance du Messager de Dieu ﷺ"],["Sahih Muslim","Livre du jeûne – Le jeûne du lundi"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('marriage','fr','{"name":"Mariage avec Khadīja","when":"vers 595","summary":"Le mariage du Prophète ﷺ avec Khadīja bint Khuwaylid, alors qu''il avait vingt-cinq ans.","disputed":"L''âge de Khadīja lors du mariage : l''avis le plus connu est quarante ans ; d''autres avis sont rapportés.","bio":"Le Prophète ﷺ travailla dans son commerce vers al-Shām ; elle vit sa loyauté et lui proposa le mariage. Elle lui donna ses enfants, à l''exception d''Ibrāhīm.","context":"Elle fut la première à croire en lui et son soutien durant les années les plus dures de l''appel.","sources":[["La Biographie prophétique — Ibn Hishām","Récit du mariage avec Khadīja"],["Les Grandes Générations — Ibn Saʿd","Notice biographique : Khadīja"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('revelation','fr','{"name":"La Révélation","when":"Ramadan – vers 610","summary":"Jibrīl apporta les premiers versets du Coran dans la grotte de Hira : « Lis, au nom de ton Seigneur qui a créé. »","disputed":"Le jour de la première révélation en Ramadan est discuté (17, 21 ou 24) ; beaucoup retiennent la Nuit du Destin comme le plus probable.","bio":"Le Prophète ﷺ avait quarante ans lorsque Jibrīl vint, l''étreignit et lui dit : « Lis. » Il retourna auprès de Khadīja le cœur frémissant ; elle le rassura et l''emmena chez Waraqa ibn Nawfal.","context":"Puis la révélation s''interrompit un temps, et la sourate al-Muddaththir fut révélée avec l''ordre d''avertir.","sources":[["Sahih al-Bukhari","Livre du commencement de la révélation, chapitre : comment commença la révélation"],["Le Noble Coran","Sourate al-ʿAlaq"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('dawah','fr','{"name":"La prédication publique","when":"vers 613","summary":"Après trois années de prédication discrète, Dieu ordonna à Son Prophète de proclamer ouvertement le message.","bio":"Le Prophète ﷺ monta sur le mont al-Ṣafā et appela Quraysh, et fut révélée la parole du Très-Haut (en substance) : « Et avertis les plus proches de tes proches. »","context":"Après cela, le mal que les polythéistes faisaient aux musulmans s''intensifia.","sources":[["Sahih al-Bukhari","Commentaire de la sourate al-Masad"],["La Biographie prophétique — Ibn Hishām","Récit de l''appel public"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha_hijra','fr','{"name":"L''émigration en Abyssinie","when":"5ᵉ année de la mission","summary":"Les musulmans fuirent avec leur foi les persécutions de Quraysh pour se réfugier auprès du Négus.","bio":"Le premier groupe partit, environ douze hommes et quatre femmes, puis des groupes plus nombreux les suivirent. Quraysh envoya une délégation auprès du Négus, qui la renvoya.","context":"Les ouvrages de biographie ont conservé le dialogue entre Jaʿfar ibn Abī Ṭālib et le Négus.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de l''émigration en Abyssinie"],["Le Commencement et la Fin — Ibn Kathīr","La première émigration"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('sorrow','fr','{"name":"L''Année de la tristesse","when":"10ᵉ année de la mission – 619","summary":"La mort d''Abū Ṭālib puis de Khadīja, et le départ du Prophète ﷺ pour Taïf.","bio":"Le Prophète ﷺ perdit son protecteur et son épouse en peu de temps, et le mal que lui faisait Quraysh s''aggrava.","context":"Elle fut ainsi nommée par les biographes.","sources":[["La Biographie prophétique — Ibn Hishām","La mort d''Abū Ṭālib et de Khadīja"],["Le Commencement et la Fin — Ibn Kathīr","L''Année de la tristesse"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('isra','fr','{"name":"Le Voyage nocturne et l''Ascension","when":"Avant l''Hégire","summary":"Le voyage nocturne du Prophète ﷺ de la Mosquée sacrée à al-Aqṣā, puis son ascension à travers les cieux.","disputed":"Le fait que le voyage ait eu lieu est certain, mais sa date est discutée ; aucune preuve authentique ne soutient la célèbre nuit du 27 Rajab.","bio":"Les cinq prières y furent prescrites, et le Prophète ﷺ vit quelques-uns des plus grands signes de son Seigneur.","context":"Le Coran l''évoque au début de la sourate al-Isrāʾ et dans la sourate al-Najm.","sources":[["Le Noble Coran","Sourate al-Isrāʾ 17:1"],["Sahih al-Bukhari","Livre des mérites des Ansār – Chapitre sur le Miʿrāj"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aqaba','fr','{"name":"Les deux serments d''al-ʿAqaba","when":"621 – 622","summary":"Une délégation des Ansār prêta serment de soutenir et protéger le Prophète ﷺ comme ils protègent leurs femmes et leurs enfants.","bio":"Lors de la première ʿAqaba, douze personnes prêtèrent serment, et lors de la seconde, soixante-treize hommes et deux femmes. Le Prophète ﷺ envoya Muṣʿab ibn ʿUmayr comme enseignant.","context":"Elle prépara directement l''Hégire vers Médine.","sources":[["La Biographie prophétique — Ibn Hishām","Récit des premier et second serments d''al-ʿAqaba"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hijra','fr','{"name":"L''Hégire vers Médine","when":"1 AH – 622","summary":"Le Prophète ﷺ quitta La Mecque pour Médine avec Abū Bakr : début du calendrier hégirien.","bio":"Ils partirent de nuit et se cachèrent dans la grotte de Thawr pendant trois jours, puis se rendirent avec un guide à Qubāʾ, puis à Médine. Ses habitants l''accueillirent avec joie.","context":"On s''en servit pour dater à l''époque de ʿUmar ibn al-Khaṭṭāb, que Dieu l''agrée.","sources":[["Sahih al-Bukhari","Livre des mérites des Ansār – Chapitre sur l''Hégire du Prophète ﷺ"],["La Biographie prophétique — Ibn Hishām","Récit de l''Hégire"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madina_state','fr','{"name":"La fondation de l''État islamique","when":"1 AH – 622/623","summary":"Construction de la Mosquée du Prophète, fraternité entre Muhājirūn et Ansār, et rédaction de la Charte de Médine.","disputed":"La Charte est rapportée par Ibn Isḥāq et d''autres, mais sa formulation et sa réunion en un seul document font débat parmi les chercheurs.","bio":"Le Prophète ﷺ commença par bâtir la mosquée, puis établit la fraternité entre les Muhājirūn et les Ansār, et organisa les relations entre les habitants de Médine par un document connu sous le nom de Ṣaḥīfa (Charte) de Médine.","context":"Ces étapes formèrent le noyau de la communauté et de l''État.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la construction de la mosquée, de la fraternité et de la Charte"],["Sahih al-Bukhari","Livre des mérites des Ansār – La fraternité"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('badr','fr','{"name":"La bataille de Badr","when":"17 Ramadan 2 AH – 624","summary":"Première bataille décisive entre les musulmans et Quraysh, remportée par les musulmans.","bio":"Le Prophète ﷺ sortit avec environ trois cent treize hommes et ils affrontèrent environ mille hommes de Quraysh ; Dieu leur donna la victoire malgré leur petit nombre et leur faible équipement.","context":"Le Coran l''a appelé le Jour du Discernement (Yawm al-Furqān).","sources":[["Le Noble Coran","Sourate al-Anfāl"],["Sahih al-Bukhari","Livre des expéditions – Bataille de Badr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uhud','fr','{"name":"La bataille d''Uhud","when":"Shawwāl 3 AH – 625","summary":"Bataille au pied du mont Uhud où Hamza et plusieurs Compagnons tombèrent en martyrs.","bio":"Elle commença par une victoire des musulmans, puis les archers désobéirent à l''ordre du Prophète ﷺ, et Khālid ibn al-Walīd contourna avec la cavalerie de Quraysh.","context":"La sourate Āl ʿImrān en parle.","sources":[["Le Noble Coran","Sourate Āl ʿImrān 3:121–179"],["Sahih al-Bukhari","Livre des expéditions – Bataille d''Uhud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khandaq','fr','{"name":"La bataille du Fossé","when":"Shawwāl 5 AH – 627","summary":"Les coalisés assiégèrent Médine ; le fossé fut creusé sur le conseil de Salmān al-Fārisī.","disputed":"Les récits divergent sur l’année de l’expédition : le plus connu est 5 de l’Hégire, certains disent 4.","bio":"Les coalisés assiégèrent Médine pendant environ un mois, et Dieu envoya contre eux un vent et des armées, et ils repartirent déçus.","context":"Des versets de la sourate al-Aḥzāb furent révélés à son sujet.","sources":[["Le Noble Coran","Sourate al-Aḥzāb"],["La Biographie prophétique — Ibn Hishām","La bataille du Fossé"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hudaybiyyah','fr','{"name":"Le traité d''al-Hudaybiya","when":"Dhū al-Qaʿda 6 AH – 628","summary":"Traité entre le Prophète ﷺ et Quraysh mettant fin à la guerre pour dix ans.","bio":"Le Prophète ﷺ partit dans l''intention d''accomplir la ʿumra et Quraysh l''en empêcha ; ils convinrent d''une trêve, à condition qu''il revienne l''année suivante. Le traité sembla pesant à certains Compagnons, mais Dieu l''a appelé une victoire.","context":"Il fut suivi du serment de Ridwān sous l''arbre.","sources":[["Le Noble Coran","Sourate al-Fatḥ"],["Sahih al-Bukhari","Livre des conditions – Les conditions dans le jihad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('fath','fr','{"name":"La conquête de La Mecque","when":"Ramadan 8 AH – 630","summary":"Le Prophète ﷺ entra à La Mecque avec dix mille Compagnons et purifia la Kaaba des idoles.","bio":"Quraysh rompit le traité, et le Prophète ﷺ marcha contre elle ; il y entra avec humilité et pardonna à ses habitants, en disant : « Allez, vous êtes libérés. »","context":"Après cela, les gens entrèrent en foule dans la religion de Dieu.","sources":[["Le Noble Coran","Sourate al-Naṣr"],["Sahih al-Bukhari","Livre des expéditions – Conquête de La Mecque"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('farewell','fr','{"name":"Le Pèlerinage d''adieu","when":"10 AH – 632","summary":"Le seul pèlerinage du Prophète ﷺ, durant lequel il prononça le grand sermon de ʿArafa.","bio":"Il prononça à ʿArafa un sermon affirmant l''inviolabilité du sang et des biens ainsi que les droits des femmes, et fut révélée la parole du Très-Haut (en substance) : « Aujourd''hui, J''ai parachevé pour vous votre religion. »","context":"Plus de cent mille Compagnons étaient avec lui.","sources":[["Sahih Muslim","Livre du Hajj – Le pèlerinage du Prophète ﷺ"],["Le Noble Coran","Sourate al-Māʾida 5:3"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('death','fr','{"name":"Mort du Prophète ﷺ","when":"Rabīʿ al-Awwal 11 AH – 632","summary":"Le Prophète ﷺ rejoignit le Compagnon suprême à Médine, à l''âge de soixante-trois ans.","disputed":"L''avis le plus répandu est qu''il mourut le lundi 12 Rabīʿ al-Awwal ; on rapporte aussi le 2 Rabīʿ al-Awwal.","bio":"Il fut malade quelques jours et ordonna à Abū Bakr de diriger la prière des gens ; il mourut dans la maison de ʿĀʾisha, que Dieu l''agrée, et y fut enterré.","context":"Abū Bakr assuma le califat après lui.","sources":[["Sahih al-Bukhari","Livre des expéditions – Chapitre sur la maladie et la mort du Prophète ﷺ"],["La Biographie prophétique — Ibn Hishām","Récit de la mort du Messager de Dieu ﷺ"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khadija','fr','{"name":"Khadīja bint Khuwaylid","when":"m. 619","summary":"Première Mère des croyants et première à avoir cru au Prophète ﷺ.","bio":"Commerçante qurayshite de richesse et de noblesse ; le Prophète ﷺ l''épousa et ne prit pas d''autre épouse tant qu''elle vécut. Elle soutint l''appel de ses biens et de sa personne.","context":"Elle mourut trois ans avant l''Hégire, et le Prophète ﷺ la mentionnait avec fidélité.","sources":[["Sahih al-Bukhari","Livre des mérites des Ansār – Le mariage du Prophète ﷺ avec Khadīja"],["Les Grandes Générations — Ibn Saʿd","Notice biographique : Khadīja"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abubakr','fr','{"name":"Abū Bakr al-Ṣiddīq","when":"m. 13 AH","summary":"Compagnon du Prophète ﷺ dans la grotte et premier des califes bien guidés.","bio":"ʿAbd Allāh ibn Abī Quḥāfa al-Taymī, le premier homme à embrasser l''islam selon le récit le plus connu ; il affranchit les opprimés et accompagna le Prophète ﷺ lors de l''Hégire. Il assuma le califat après la mort du Prophète ﷺ.","context":"Il combattit les apostats et fit rassembler le Coran en feuillets sur le conseil de ʿUmar.","sources":[["Sahih al-Bukhari","Livre des vertus des Compagnons"],["Les Grandes Générations — Ibn Saʿd","Notice biographique : Abū Bakr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('umar','fr','{"name":"ʿUmar ibn al-Khaṭṭāb","when":"m. 23 AH","summary":"Al-Fārūq, deuxième calife bien guidé ; sa conversion renforça l''islam.","bio":"Des Banū ʿAdī, il était connu pour sa fermeté dans la vérité et pour sa justice. Il embrassa l''islam à La Mecque, participa à toutes les batailles, et exerça le califat dix ans, durant lesquels furent conquis al-Shām, l''Irak et l''Égypte.","context":"Il établit le calendrier hégirien et institua les registres (dīwāns).","sources":[["Sahih al-Bukhari","Livre des vertus des Compagnons"],["Le Commencement et la Fin — Ibn Kathīr","Le califat de ʿUmar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uthman','fr','{"name":"ʿUthmān ibn ʿAffān","when":"m. 35 AH","summary":"Dhū al-Nūrayn, troisième calife bien guidé.","bio":"Il épousa deux filles du Prophète ﷺ, Ruqayya puis Umm Kulthūm. Il émigra en Abyssinie puis à Médine, équipa l''armée de la Détresse (ʿUsra), et unifia les exemplaires du Coran en un seul codex.","context":"Il fut martyrisé lors des troubles de l''an 35 AH.","sources":[["Sahih al-Bukhari","Livre des vertus des Compagnons"],["Les Grandes Générations — Ibn Saʿd","Notice biographique : ʿUthmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('ali','fr','{"name":"ʿAlī ibn Abī Ṭālib","when":"m. 40 AH","summary":"Cousin du Prophète ﷺ, époux de Fāṭima et quatrième calife bien guidé.","bio":"Il grandit dans la maison du Prophète ﷺ et embrassa l''islam jeune. Il dormit dans son lit la nuit de l''Hégire et restitua les dépôts, et participa aux batailles sauf Tabūk.","context":"Il était connu pour son savoir, son courage et son jugement.","sources":[["Sahih al-Bukhari","Livre des vertus des Compagnons"],["La Biographie prophétique — Ibn Hishām","ʿAlī dormant dans le lit du Prophète"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aisha','fr','{"name":"ʿĀʾisha bint Abī Bakr","when":"m. 58 AH","summary":"Mère des croyants, parmi les Compagnons ayant le plus transmis de hadiths et de jurisprudence.","bio":"Le Prophète ﷺ l''épousa à La Mecque et consomma le mariage à Médine. Elle rapporta plus de deux mille hadiths, et les grands Compagnons l''interrogeaient.","context":"Le Prophète ﷺ mourut dans sa maison et y fut enterré.","sources":[["Les Grandes Générations — Ibn Saʿd","Notice biographique : ʿĀʾisha"],["Sahih al-Bukhari","Livre des vertus des Compagnons"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('bilal','fr','{"name":"Bilāl ibn Rabāḥ","when":"m. vers 20 AH","summary":"Premier muezzin de l''islam, connu pour sa fermeté sous la torture.","disputed":"L''année et le lieu de sa mort sont discutés dans les sources biographiques (Damas ou Alep).","bio":"Esclave abyssin d''Umayya ibn Khalaf, torturé pour son islam, il disait « Un, Un (Aḥad, Aḥad) » ; Abū Bakr l''acheta et l''affranchit.","context":"Il fit l''appel à la prière le jour de la Conquête de La Mecque depuis le sommet de la Kaaba.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la torture de Bilāl"],["Sahih al-Bukhari","Livre des mérites des Ansār"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hamza','fr','{"name":"Hamza ibn ʿAbd al-Muṭṭalib","when":"m. 3 AH","summary":"Oncle du Prophète ﷺ et Lion de Dieu, maître des martyrs.","bio":"Il embrassa l''islam la deuxième année de la mission et les musulmans en furent renforcés. Il se distingua à Badr et fut martyrisé à Uhud.","context":"Waḥshī ibn Ḥarb le tua sur l''ordre de Hind bint ʿUtba.","sources":[["Sahih al-Bukhari","Livre des expéditions – La mort de Hamza"],["La Biographie prophétique — Ibn Hishām","La bataille d''Uhud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abutalib','fr','{"name":"Abū Ṭālib ibn ʿAbd al-Muṭṭalib","when":"m. 619","summary":"Oncle du Prophète ﷺ, son tuteur et son protecteur face à Quraysh.","bio":"Il prit en charge le Prophète ﷺ après son grand-père et le protégea du mal de Quraysh pendant dix ans après la mission, mais il mourut sur la religion de son peuple.","context":"Il est rapporté dans les deux Ṣaḥīḥ qu''il ne prononça pas la profession de foi à sa mort.","sources":[["Sahih al-Bukhari","Livre des mérites des Ansār – L''histoire d''Abū Ṭālib"],["La Biographie prophétique — Ibn Hishām","La mort d''Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('najashi','fr','{"name":"Le Négus Aṣḥama","when":"m. 9 AH","summary":"Le roi juste d''Abyssinie qui accueillit les émigrés.","bio":"Il écouta la sourate Maryam récitée par Jaʿfar ibn Abī Ṭālib et pleura, refusa de livrer les musulmans à Quraysh, et embrassa l''islam.","context":"Le Prophète ﷺ pria sur lui la prière funéraire in absentia à sa mort.","sources":[["Sahih al-Bukhari","Livre des funérailles – La prière sur le Négus"],["La Biographie prophétique — Ibn Hishām","Récit de l''émigration en Abyssinie"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('musab','fr','{"name":"Muṣʿab ibn ʿUmayr","when":"m. 3 AH","summary":"Premier ambassadeur de l''islam, envoyé par le Prophète ﷺ pour instruire les habitants de Médine.","bio":"Jeune homme choyé de La Mecque qui renonça à l''aisance pour sa religion. Beaucoup d''Ansār embrassèrent l''islam par son entremise, parmi eux Usayd ibn Ḥuḍayr et Saʿd ibn Muʿādh.","context":"Il porta l''étendard des musulmans à Uhud et fut martyrisé.","sources":[["Sahih al-Bukhari","Livre des expéditions – Bataille d''Uhud"],["La Biographie prophétique — Ibn Hishām","Récit de Muṣʿab"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('salman','fr','{"name":"Salmān al-Fārisī","when":"m. vers 35 AH","summary":"Le chercheur de vérité venu de Perse et conseiller de la bataille du Fossé.","disputed":"Son âge à sa mort est très discuté selon les récits.","bio":"Il voyagea depuis la Perse à la recherche de la vérité jusqu''à atteindre Médine, où il embrassa l''islam. Il proposa de creuser le fossé.","context":"Le Prophète ﷺ dit : « Salmān est des nôtres, les gens de la Maison. »","sources":[["La Biographie prophétique — Ibn Hishām","Récit de Salmān"],["Les Grandes Générations — Ibn Saʿd","Notice biographique : Salmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khalid','fr','{"name":"Khālid ibn al-Walīd","when":"m. 21 AH","summary":"L''Épée dégainée de Dieu, grand chef militaire.","bio":"L''un des cavaliers de Quraysh, qui mena le mouvement d''encerclement à Uhud, puis embrassa l''islam avant la Conquête, participa à Mūta et commanda des armées après le Prophète ﷺ.","context":"Le Prophète ﷺ le nomma l''Épée de Dieu.","sources":[["Sahih al-Bukhari","Livre des expéditions – Bataille de Mūta"],["Le Commencement et la Fin — Ibn Kathīr","Notice biographique : Khālid"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abdurrahman','fr','{"name":"ʿAbd al-Raḥmān ibn ʿAwf","when":"m. 32 AH","summary":"L''un des dix promis au Paradis et le marchand intègre parmi les Compagnons.","bio":"Il émigra deux fois, et le Prophète ﷺ établit la fraternité entre lui et Saʿd ibn al-Rabīʿ, mais il refusa les biens de son frère et dit : « Montrez-moi le marché. »","context":"Il donna une grande fortune en aumône dans la voie de Dieu.","sources":[["Sahih al-Bukhari","Livre des mérites des Ansār – La fraternité"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('arabia_pre','fr','{"name":"L’Arabie avant la naissance du Prophète ﷺ","when":"Avant 570","summary":"La société tribale de l’Arabie et la place des Quraych et de La Mecque avant la naissance du Prophète ﷺ.","bio":"La vie en Arabie reposait sur la tribu, le commerce et les caravanes ; les Quraych veillaient sur la Maison sacrée à La Mecque, et le culte des idoles était répandu autour de la Kaʿba. Des juifs et des chrétiens vivaient dans certaines villes et marges de la péninsule, et certains Arabes qui rejetaient les idoles étaient appelés ḥanīfs.","context":"La sourate Quraych évoque les voyages d’hiver et d’été pour lesquels les Quraych étaient connus.","sources":[["La Biographie prophétique — Ibn Hishām","Récit sur ʿAmr ibn Luḥayy et le culte des idoles"],["Le Noble Coran","Sourate Quraych"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('childhood','fr','{"name":"Enfance et orphelinat","when":"570 – environ 578","summary":"Le Prophète ﷺ grandit orphelin, entre l’allaitement chez les Banū Saʿd et la prise en charge de son grand-père puis de son oncle.","bio":"Il fut allaité chez les Banū Saʿd par Ḥalīma al-Saʿdiyya, puis revint auprès de sa mère Āmina, qui mourut à al-Abwāʾ au retour de Médine alors qu’il avait environ six ans ; son grand-père ʿAbd al-Muṭṭalib se chargea de lui, puis son oncle Abū Ṭālib.","context":"Les biographies indiquent qu’il avait environ huit ans à la mort de son grand-père.","disputed":"Les récits divergent sur son âge à la mort de sa mère et de son grand-père, et sur l’ordre de certains événements.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de son allaitement chez les Banū Saʿd"],["La Biographie prophétique — Ibn Hishām","Récit de la mort d’Āmina et de la prise en charge par ʿAbd al-Muṭṭalib et Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('youth','fr','{"name":"Jeunesse et loyauté","when":"Environ 580 – 595","summary":"Son travail de berger, ses voyages de commerce et sa réputation de franchise et de loyauté avant la mission.","bio":"Il fut berger pour les gens de La Mecque, voyagea pour le commerce, devint connu parmi les siens comme le véridique et le loyal, et assista avec ses oncles au pacte des Fuḍūl.","context":"Certaines biographies mentionnent un voyage au Shām avec son oncle Abū Ṭālib dans son jeune âge, et une rencontre avec le moine Baḥīrā.","disputed":"Les récits divergent sur les détails du voyage au Shām, sur l’authenticité de l’histoire de Baḥīrā et sur son âge lors du pacte des Fuḍūl.","sources":[["Sahih al-Bukhari","Livre du louage, chapitre : garder les moutons pour quelques qirāṭ"],["La Biographie prophétique — Ibn Hishām","Récit du pacte des Fuḍūl"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba_rebuild','fr','{"name":"Les Quraych reconstruisent la Kaʿba ; le Prophète ﷺ est choisi comme arbitre","when":"Environ 605 (cinq ans environ avant la mission)","summary":"Les Quraych rénovèrent la Kaʿba et prirent le Prophète ﷺ comme arbitre pour la pose de la Pierre noire.","bio":"Les tribus des Quraych se disputèrent sur celui qui poserait la Pierre noire et convinrent de s’en remettre au premier arrivant ; ce fut le Prophète ﷺ, qui plaça la pierre sur un tissu, fit porter celui-ci par toutes les tribus, puis la posa de sa main.","context":"Dans les récits biographiques, le Prophète ﷺ avait environ trente-cinq ans.","disputed":"Les récits divergent sur son âge lors de la reconstruction de la Kaʿba ; le chiffre le plus connu est d’environ trente-cinq ans.","sources":[["La Biographie prophétique — Ibn Hishām","Récit de la reconstruction de la Kaaba par Quraysh"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('secret_dawah','fr','{"name":"L’appel discret","when":"Environ 610 – 613","summary":"Les premières années de l’appel, fait discrètement auprès des proches et des personnes de confiance avant d’être rendu public.","bio":"Le Prophète ﷺ appela discrètement ceux en qui il avait confiance ; Khadīja, Abū Bakr, ʿAlī, Zayd ibn Ḥāritha et d’autres le suivirent, et les musulmans cachaient leur culte.","context":"Les biographies mentionnent que la maison d’al-Arqam ibn Abī al-Arqam fut l’un des lieux de réunion des musulmans.","disputed":"On rapporte généralement que la phase discrète dura environ trois ans ; les récits divergent sur sa durée.","sources":[["La Biographie prophétique — Ibn Hishām","Récit du début de l’appel et des premiers convertis"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('persecution','fr','{"name":"Persécution des premiers musulmans","when":"À partir d’environ 613","summary":"Les violences subies par le Prophète ﷺ et par les musulmans vulnérables après que l’appel fut rendu public.","bio":"Beaucoup de musulmans vulnérables furent torturés et maltraités, dont Bilāl ibn Rabāḥ ; Abū Bakr en racheta plusieurs et les affranchit, et le Prophète ﷺ lui-même subit des violences et des moqueries.","context":"Cette épreuve poussa certains musulmans à émigrer en Abyssinie.","sources":[["La Biographie prophétique — Ibn Hishām","Récit des violences subies par les musulmans"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('boycott','fr','{"name":"Le boycott dans le vallon d’Abū Ṭālib","when":"Environ 616 – 619 (7e à 10e année de la mission)","summary":"Le boycott des Banū Hāshim et des Banū al-Muṭṭalib par les Quraych, confinés dans le vallon.","bio":"Les Quraych convinrent de boycotter les Banū Hāshim et les Banū al-Muṭṭalib dans le commerce et le mariage ; le Prophète ﷺ et ceux qui l’accompagnaient se réfugièrent un temps dans le vallon d’Abū Ṭālib, jusqu’à l’annulation du pacte.","context":"Elle fut suivie de l’Année de la tristesse.","disputed":"Les récits divergent sur son début et sa durée : le chiffre le plus connu est d’environ trois ans, certains disent moins.","sources":[["La Biographie prophétique — Ibn Hishām","Récit du document du pacte et du siège du vallon"],["Le Commencement et la Fin — Ibn Kathīr","Le siège des Banū Hāshim dans le vallon"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif_trip','fr','{"name":"Le voyage à Ṭāʾif","when":"Shawwāl, 10e année de la mission – environ 619","summary":"Le voyage du Prophète ﷺ à Ṭāʾif pour appeler ses habitants, après la mort d’Abū Ṭālib et de Khadīja.","bio":"Il partit avec Zayd ibn Ḥāritha et proposa l’islam aux chefs de Thaqīf, qui le rejetèrent et lancèrent contre lui leurs insensés, qui lui jetèrent des pierres ; il retourna ensuite à La Mecque sous la protection d’al-Muṭʿim ibn ʿAdī.","context":"Le Ṣaḥīḥ contient le récit de ʿĀʾisha sur le jour le plus dur que le Prophète ﷺ ait connu, à Ṭāʾif.","sources":[["Sahih al-Bukhari","Livre du commencement de la création"],["La Biographie prophétique — Ibn Hishām","Récit de son voyage à Ṭāʾif"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khaybar','fr','{"name":"L’expédition de Khaybar","when":"Muḥarram 7 de l’Hégire – 628","summary":"L’expédition des musulmans contre les forteresses des juifs de Khaybar, au nord de Médine, après le traité d’al-Ḥudaybiya.","bio":"Au retour d’al-Ḥudaybiya, le Prophète ﷺ marcha sur Khaybar, assiégea et prit ses forteresses, et laissa ses habitants cultiver la terre pour la moitié de la récolte.","context":"Le Ṣaḥīḥ rapporte que le Prophète ﷺ donna l’étendard à ʿAlī ibn Abī Ṭālib lors de cette expédition.","disputed":"Les récits divergent sur le mois : le plus connu est Muḥarram de la septième année ; d’autres mois sont aussi cités.","sources":[["Sahih al-Bukhari","Livre des expéditions, chapitre : l’expédition de Khaybar"],["La Biographie prophétique — Ibn Hishām","Récit de l’expédition de Khaybar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muta','fr','{"name":"La bataille de Muʾta","when":"Jumādā al-Ūlā 8 de l’Hégire – 629","summary":"Une bataille entre les musulmans et l’armée byzantine et ses alliés aux confins du Shām, où trois chefs musulmans tombèrent en martyrs.","bio":"Le Prophète ﷺ envoya une armée sous le commandement de Zayd ibn Ḥāritha, puis de Jaʿfar ibn Abī Ṭālib, puis de ʿAbd Allāh ibn Rawāḥa ; tous trois tombèrent en martyrs, et Khālid ibn al-Walīd prit l’étendard et ramena l’armée.","context":"Dans le récit d’al-Bukhārī, le Prophète ﷺ appela Khālid une épée parmi les épées de Dieu à cette occasion.","disputed":"Les récits varient dans les effectifs donnés pour les deux armées et dans la description de l’issue.","sources":[["Sahih al-Bukhari","Livre des expéditions, chapitre : l’expédition de Muʾta en terre du Shām"],["La Biographie prophétique — Ibn Hishām","Récit de l’expédition de Muʾta"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hunayn','fr','{"name":"La bataille de Ḥunayn","when":"Shawwāl 8 de l’Hégire – 630","summary":"La bataille des musulmans contre Hawāzin et Thaqīf après la conquête de La Mecque.","bio":"Les musulmans partirent avec une grande armée ; l’ennemi les surprit dans la vallée de Ḥunayn et leurs rangs vacillèrent, mais le Prophète ﷺ et ceux qui étaient avec lui tinrent bon, les musulmans se ressaisirent et l’emportèrent.","context":"Le Coran évoque ce jour dans la sourate al-Tawba ; les musulmans se dirigèrent ensuite vers Ṭāʾif.","sources":[["Sahih al-Bukhari","Livre des expéditions, chapitre : la parole de Dieu « et le jour de Ḥunayn »"],["Le Noble Coran","Sourate al-Tawba 9:25–26"],["La Biographie prophétique — Ibn Hishām","Récit de l’expédition de Ḥunayn"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('tabuk','fr','{"name":"L’expédition de Tabūk","when":"Rajab 9 de l’Hégire – 630","summary":"La marche du Prophète ﷺ avec une grande armée vers Tabūk, aux confins du Shām ; aucun combat n’eut lieu.","bio":"Le Prophète ﷺ partit en un temps de dureté et de chaleur pour faire face aux rassemblements byzantins dont il avait entendu parler ; il atteignit Tabūk, y resta quelques jours et revint sans combattre. Son armée fut appelée l’armée de la détresse.","context":"Trois Compagnons restèrent en arrière et furent ensuite pardonnés.","disputed":"Les récits varient sur la durée de son séjour à Tabūk.","sources":[["Sahih al-Bukhari","Livre des expéditions, chapitre : l’expédition de Tabūk"],["Le Noble Coran","Sourate al-Tawba 9:117–118"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('illness','fr','{"name":"La dernière maladie du Prophète ﷺ","when":"Fin de Ṣafar – Rabīʿ al-Awwal 11 de l’Hégire – 632","summary":"Les derniers jours de maladie du Prophète ﷺ dans la maison de ʿĀʾisha jusqu’à sa mort.","bio":"Sa maladie s’aggrava ; il demanda à ses épouses la permission d’être soigné chez ʿĀʾisha, ce qu’elles acceptèrent, et il demanda à Abū Bakr de diriger la prière.","context":"La préparation de l’armée d’Usāma ibn Zayd précéda sa maladie.","disputed":"Les récits divergent sur le début et la durée de la maladie : le chiffre le plus connu est d’environ dix jours, certains disent treize.","sources":[["Sahih al-Bukhari","Livre des expéditions, chapitre : la maladie et la mort du Prophète ﷺ"],["Sahih al-Bukhari","Livre de l’appel à la prière, chapitre : les gens de science et de mérite ont le plus de droit à diriger la prière"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muhammad','en','{"name":"Prophet Muhammad ﷺ","when":"570 – 632 CE","summary":"Seal of the prophets and messengers, Muhammad ibn ʿAbd Allāh ibn ʿAbd al-Muṭṭalib of the Banū Hāshim, of Quraysh.","bio":"He was born in Makkah in the Year of the Elephant and grew up an orphan; among his people he was known as the Truthful, the Trustworthy. He was sent at the age of forty, called to the oneness of God for twenty-three years, and then died in Madinah al-Munawwarah.","context":"He lived in a tribal environment in the Arabian Peninsula dominated by idol worship, and his message came with monotheism and the building of a new society based on justice and brotherhood.","sources":[["The Prophetic Biography — Ibn Hishām","Parts 1 and 2"],["Sahih al-Bukhari","Book of Virtues"],["The Sealed Nectar — al-Mubārakfūrī","Various places"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('companions','en','{"name":"The Companions","when":"610 – 632 CE","summary":"Those who met the Prophet ﷺ as believers in him and died holding that faith.","bio":"The definition of a Companion according to the majority of hadith scholars: one who met the Prophet ﷺ as a believer in him and died as a Muslim. They carried the message, transmitted the Sunna and founded the state after him.","context":"They fall into different ranks: the foremost early believers, the emigrants to Abyssinia, the people of Badr, those who gave the Pledge of Riḍwān, and those who embraced Islam in the year of the Conquest.","sources":[["The Great Classes — Ibn Saʿd","Introduction to the Ṭabaqāt"],["al-Iṣāba fī Tamyīz al-Ṣaḥāba — Ibn Ḥajar","Introduction"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('makkah','en','{"name":"Makkah al-Mukarramah","when":"Birth and upbringing of the Prophet ﷺ","summary":"Birthplace of the Prophet ﷺ, home of the revelation and seat of the Noble Kaʿba.","bio":"A city in a valley without cultivation in the Hijaz, containing the Sacred House; it was a commercial and religious centre led by Quraysh.","context":"The Prophet ﷺ spent fifty-three years there before the Hijra, and conquered it in 8 AH.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the building of the Kaʿba"],["The Noble Qurʾān","Sūrat al-Balad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madinah','en','{"name":"Madinah al-Munawwarah","when":"From 622 CE","summary":"The city of the Hijra, capital of the first Islamic state and burial place of the Prophet ﷺ.","bio":"It was called Yathrib and was inhabited by the Aws and the Khazraj and Jewish tribes. After the Hijra the Prophet ﷺ changed its name to Ṭayba and al-Madīna.","context":"It contains the Prophet’s Mosque; the expeditions set out from it, and the Muslim community was built in it.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the Hijra"],["Sahih al-Bukhari","Book of the Virtues of Madinah"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hira','en','{"name":"Cave of Ḥirāʾ","when":"Jabal al-Nūr – Makkah","summary":"The cave where the Prophet ﷺ used to worship and where the first revelation came.","bio":"A small cave on Jabal al-Nūr, about three miles from Makkah, where the Prophet ﷺ used to retreat for devotion for a number of nights.","context":"The first verses of Sūrat al-ʿAlaq were revealed in it.","sources":[["Sahih al-Bukhari","Book of the Beginning of the Revelation"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba','en','{"name":"The Noble Kaʿba","when":"Qibla of the Muslims","summary":"The Sacred House whose foundations were raised by Ibrāhīm and Ismāʿīl, peace be upon them.","bio":"Quraysh rebuilt it about five years before the mission; the Prophet ﷺ took part in this and arbitrated in the placing of the Black Stone.","context":"The Prophet ﷺ cleansed it of idols on the day of the Conquest of Makkah.","sources":[["The Prophetic Biography — Ibn Hishām","Account of Quraysh’s rebuilding of the Kaʿba"],["The Noble Qurʾān","Sūrat al-Baqara 2:127"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif','en','{"name":"Ṭāʾif","when":"10th year of the mission","summary":"The city the Prophet ﷺ went to in order to call its people, who rejected him.","bio":"The Prophet ﷺ went out to it with Zayd ibn Ḥāritha after the death of Abū Ṭālib and Khadīja; its foolish ones harmed him and threw stones at him.","context":"It is reported in the Ṣaḥīḥ that Jibrīl offered to bring the two mountains together upon them, and he said: “Rather, I hope that God will bring forth from their loins those who worship God alone.”","sources":[["Sahih al-Bukhari","Book of the Beginning of Creation"],["Sahih Muslim","Book of Jihād and Expeditions"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha','en','{"name":"Abyssinia","when":"Two migrations, 615 and 616 CE","summary":"The land to which the first Muslims emigrated under the protection of the just Negus.","bio":"The Prophet ﷺ said to the Muslims: “There is a king there with whom no one is wronged.” They stayed there secure in their religion.","context":"Among the most prominent who emigrated there were ʿUthmān ibn ʿAffān, his wife Ruqayya, and Jaʿfar ibn Abī Ṭālib.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the emigration to the land of Abyssinia"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('elephant','en','{"name":"Year of the Elephant","when":"c. 570 CE","summary":"The attempt of Abraha the Abyssinian to destroy the Kaʿba and the destruction of his army.","bio":"Abraha led an army including elephants to Makkah, and God sent upon it flocks of birds. In this year the Prophet ﷺ was born.","context":"Sūrat al-Fīl mentions it, and the Arabs used it to date events.","sources":[["The Noble Qurʾān","Sūrat al-Fīl"],["The Prophetic Biography — Ibn Hishām","Account of the People of the Elephant"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('birth','en','{"name":"Birth of the Prophet ﷺ","when":"12 Rabīʿ al-Awwal – Year of the Elephant","summary":"The birth of Muhammad ibn ʿAbd Allāh in Makkah, an orphan.","disputed":"The day of the month is disputed: the best-known is 12 Rabīʿ al-Awwal; 2, 8 or 9 are also reported. Contemporary astronomers favour 9 Rabīʿ al-Awwal.","bio":"He was born after the death of his father ʿAbd Allāh, and his grandfather ʿAbd al-Muṭṭalib and then his uncle Abū Ṭālib took him in. He was put out to nurse among the Banū Saʿd with Ḥalīma al-Saʿdiyya.","context":"What is agreed upon is that he was born on a Monday in the Year of the Elephant.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the birth of the Messenger of God ﷺ"],["Sahih Muslim","Book of Fasting – Fasting on Monday"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('marriage','en','{"name":"Marriage to Khadīja","when":"c. 595 CE","summary":"The marriage of the Prophet ﷺ to Khadīja bint Khuwaylid when he was twenty-five.","disputed":"Khadīja’s age at marriage: the best-known view is forty; others are reported.","bio":"The Prophet ﷺ worked in her trade to al-Shām, she saw his trustworthiness and proposed marriage to him. She bore him his children except Ibrāhīm.","context":"She was the first to believe in him and his support in the hardest years of the call.","sources":[["The Prophetic Biography — Ibn Hishām","Report of the marriage to Khadīja"],["The Great Classes — Ibn Saʿd","Biographical entry: Khadīja"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('revelation','en','{"name":"The Revelation","when":"Ramadan – c. 610 CE","summary":"Jibrīl brought the first verses of the Qurʾān in the Cave of Ḥirāʾ: “Read in the name of your Lord who created.”","disputed":"The day of the first revelation in Ramadan is disputed (17th, 21st or 24th); many consider the Night of Power most likely.","bio":"The Prophet ﷺ was forty when Jibrīl came and embraced him and said: “Read.” He returned to Khadīja with his heart trembling; she reassured him and took him to Waraqa ibn Nawfal.","context":"Then the revelation paused for a time, and Sūrat al-Muddaththir was revealed with the command to warn.","sources":[["Sahih al-Bukhari","Book of the Beginning of the Revelation, chapter: how the revelation began"],["The Noble Qurʾān","Sūrat al-ʿAlaq"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('dawah','en','{"name":"The Public Call","when":"c. 613 CE","summary":"After three years of secret preaching, God commanded His Prophet to proclaim the message openly.","bio":"The Prophet ﷺ ascended Mount al-Ṣafā and called out to Quraysh, and the saying of the Most High was revealed (meaning): “And warn your closest kinsmen.”","context":"After that the harm done by the polytheists to the Muslims intensified.","sources":[["Sahih al-Bukhari","Commentary on Sūrat al-Masad"],["The Prophetic Biography — Ibn Hishām","Account of the public call"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha_hijra','en','{"name":"Migration to Abyssinia","when":"5th year of the mission","summary":"Muslims fled with their faith from the persecution of Quraysh to the Negus.","bio":"The first group departed, about twelve men and four women, and larger groups followed them. Quraysh sent a delegation to the Negus, who sent them back.","context":"The books of biography preserved the dialogue between Jaʿfar ibn Abī Ṭālib and the Negus.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the emigration to Abyssinia"],["The Beginning and the End — Ibn Kathīr","The first emigration"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('sorrow','en','{"name":"Year of Sorrow","when":"10th year of the mission – 619 CE","summary":"The deaths of Abū Ṭālib and then Khadīja, and the Prophet’s ﷺ journey to Ṭāʾif.","bio":"The Prophet ﷺ lost his protector and his wife within a short period, and the harm from Quraysh grew more intense.","context":"It was named thus by the biographers.","sources":[["The Prophetic Biography — Ibn Hishām","The deaths of Abū Ṭālib and Khadīja"],["The Beginning and the End — Ibn Kathīr","The Year of Sorrow"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('isra','en','{"name":"The Night Journey and Ascension","when":"Before the Hijra","summary":"The Prophet’s ﷺ night journey from the Sacred Mosque to al-Aqṣā, then his ascent through the heavens.","disputed":"That the journey took place is certain, but its date is disputed; no sound evidence supports the well-known 27th of Rajab.","bio":"The five prayers were made obligatory in it, and the Prophet ﷺ saw some of the greatest signs of his Lord.","context":"The Qurʾān mentions it at the beginning of Sūrat al-Isrāʾ and in Sūrat al-Najm.","sources":[["The Noble Qurʾān","Sūrat al-Isrāʾ 17:1"],["Sahih al-Bukhari","Book of the Virtues of the Anṣār – Chapter on the Miʿrāj"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aqaba','en','{"name":"The Two Pledges of ʿAqaba","when":"621 – 622 CE","summary":"A delegation of the Anṣār pledged to support and protect the Prophet ﷺ as they would protect their own women and children.","bio":"At the First ʿAqaba twelve gave the pledge, and at the Second seventy-three men and two women. The Prophet ﷺ sent Muṣʿab ibn ʿUmayr as a teacher.","context":"It directly paved the way for the Hijra to Madinah.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the First and Second Pledges of ʿAqaba"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hijra','en','{"name":"The Hijra to Madinah","when":"1 AH – 622 CE","summary":"The Prophet ﷺ moved with Abū Bakr from Makkah to Madinah, the start of the Hijri calendar.","bio":"The two left by night and hid in the Cave of Thawr for three days, then travelled with a guide to Qubāʾ and then Madinah. Its people received him with joy.","context":"It was used for dating in the time of ʿUmar ibn al-Khaṭṭāb, may God be pleased with him.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Anṣār – Chapter on the Prophet’s ﷺ Hijra"],["The Prophetic Biography — Ibn Hishām","Account of the Hijra"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madina_state','en','{"name":"Building the Islamic State","when":"1 AH – 622/623 CE","summary":"Building the Prophet’s Mosque, the brotherhood between Muhājirūn and Anṣār, and the writing of the Charter of Madinah.","disputed":"The Charter is reported by Ibn Isḥāq and others, but its wording and its compilation into a single document are debated among scholars.","bio":"The Prophet ﷺ began by building the mosque, then established brotherhood between the Muhājirūn and the Anṣār, and regulated relations among the people of Madinah with a document known as the Ṣaḥīfa (Charter) of Madinah.","context":"These steps formed the nucleus of the community and the state.","sources":[["The Prophetic Biography — Ibn Hishām","Account of building the mosque, the brotherhood and the Charter"],["Sahih al-Bukhari","Book of the Virtues of the Anṣār – The brotherhood"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('badr','en','{"name":"Battle of Badr","when":"17 Ramadan 2 AH – 624 CE","summary":"The first decisive battle between the Muslims and Quraysh, won by the Muslims.","bio":"The Prophet ﷺ went out with about three hundred and thirteen men and they faced about a thousand of Quraysh; God gave them victory despite their small numbers and equipment.","context":"The Qurʾān called it the Day of Criterion (Yawm al-Furqān).","sources":[["The Noble Qurʾān","Sūrat al-Anfāl"],["Sahih al-Bukhari","Book of Military Expeditions – Battle of Badr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uhud','en','{"name":"Battle of Uḥud","when":"Shawwāl 3 AH – 625 CE","summary":"A battle at Mount Uḥud in which Ḥamza and a number of Companions were martyred.","bio":"It began with victory for the Muslims, then the archers disobeyed the Prophet’s ﷺ command, and Khālid ibn al-Walīd circled around with the cavalry of Quraysh.","context":"Sūrat Āl ʿImrān speaks about it.","sources":[["The Noble Qurʾān","Sūrat Āl ʿImrān 3:121–179"],["Sahih al-Bukhari","Book of Military Expeditions – Battle of Uḥud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khandaq','en','{"name":"Battle of the Trench","when":"Shawwāl 5 AH – 627 CE","summary":"The confederates allied to besiege Madinah, and the trench was dug on the advice of Salmān al-Fārisī.","disputed":"Reports differ on the year of the campaign: the best-known view is 5 AH, and some say 4 AH.","bio":"The confederates besieged Madinah for about a month, and God sent upon them a wind and soldiers, and they departed disappointed.","context":"Verses of Sūrat al-Aḥzāb were revealed about it.","sources":[["The Noble Qurʾān","Sūrat al-Aḥzāb"],["The Prophetic Biography — Ibn Hishām","The Battle of the Trench"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hudaybiyyah','en','{"name":"Treaty of al-Ḥudaybiya","when":"Dhū al-Qaʿda 6 AH – 628 CE","summary":"A treaty between the Prophet ﷺ and Quraysh to halt the war for ten years.","bio":"The Prophet ﷺ set out intending ʿumra and Quraysh prevented him, so they agreed to a truce on his returning the following year. The treaty seemed burdensome to some Companions, but God called it a victory.","context":"It was followed by the Pledge of Riḍwān under the tree.","sources":[["The Noble Qurʾān","Sūrat al-Fatḥ"],["Sahih al-Bukhari","Book of Conditions – Conditions in jihād"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('fath','en','{"name":"Conquest of Makkah","when":"Ramadan 8 AH – 630 CE","summary":"The Prophet ﷺ entered Makkah with ten thousand of his Companions and cleansed the Kaʿba of idols.","bio":"Quraysh broke the treaty, so the Prophet ﷺ marched on it; he entered humbly and pardoned its people, saying: “Go, for you are the released.”","context":"After it people entered the religion of God in crowds.","sources":[["The Noble Qurʾān","Sūrat al-Naṣr"],["Sahih al-Bukhari","Book of Military Expeditions – Conquest of Makkah"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('farewell','en','{"name":"Farewell Pilgrimage","when":"10 AH – 632 CE","summary":"The Prophet’s ﷺ only pilgrimage, in which he gave the comprehensive sermon of ʿArafa.","bio":"He gave a sermon at ʿArafa affirming the sanctity of blood and property and the rights of women, and the saying of the Most High was revealed (meaning): “This day I have perfected your religion for you.”","context":"More than a hundred thousand Companions were with him.","sources":[["Sahih Muslim","Book of Ḥajj – The Prophet’s ﷺ pilgrimage"],["The Noble Qurʾān","Sūrat al-Māʾida 5:3"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('death','en','{"name":"Death of the Prophet ﷺ","when":"Rabīʿ al-Awwal 11 AH – 632 CE","summary":"The Prophet ﷺ passed to the Highest Companion in Madinah at the age of sixty-three.","disputed":"The most widely held view is that he died on Monday 12 Rabīʿ al-Awwal; 2 Rabīʿ al-Awwal is also reported.","bio":"He was ill for some days and commanded Abū Bakr to lead the people in prayer; he died in the house of ʿĀʾisha, may God be pleased with her, and was buried in it.","context":"Abū Bakr took over the caliphate after him.","sources":[["Sahih al-Bukhari","Book of Military Expeditions – Chapter on the Prophet’s ﷺ illness and death"],["The Prophetic Biography — Ibn Hishām","Account of the death of the Messenger of God ﷺ"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khadija','en','{"name":"Khadīja bint Khuwaylid","when":"d. 619 CE","summary":"The first Mother of the Believers and the first to believe in the Prophet ﷺ.","bio":"A Qurayshi businesswoman of wealth and nobility; the Prophet ﷺ married her and took no other wife while she lived. She supported the call with her wealth and her self.","context":"She died three years before the Hijra, and the Prophet ﷺ used to mention her with loyalty.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Anṣār – The Prophet’s ﷺ marriage to Khadīja"],["The Great Classes — Ibn Saʿd","Biographical entry: Khadīja"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abubakr','en','{"name":"Abū Bakr al-Ṣiddīq","when":"d. 13 AH","summary":"Companion of the Prophet ﷺ in the cave and the first of the Rightly Guided Caliphs.","bio":"ʿAbd Allāh ibn Abī Quḥāfa al-Taymī, the first man to accept Islam in the well-known report; he freed the oppressed and accompanied the Prophet ﷺ on the Hijra. He took on the caliphate after his death ﷺ.","context":"He fought the apostates and collected the Qurʾān into pages on the advice of ʿUmar.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Companions"],["The Great Classes — Ibn Saʿd","Biographical entry: Abū Bakr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('umar','en','{"name":"ʿUmar ibn al-Khaṭṭāb","when":"d. 23 AH","summary":"al-Fārūq, the second Rightly Guided Caliph; his conversion strengthened Islam.","bio":"From the Banū ʿAdī, he was known for firmness in the truth and for justice. He accepted Islam in Makkah and witnessed all the battles, and held the caliphate for ten years in which al-Shām, Iraq and Egypt were conquered.","context":"He established the Hijri calendar and set up the registers (dīwāns).","sources":[["Sahih al-Bukhari","Book of the Virtues of the Companions"],["The Beginning and the End — Ibn Kathīr","The caliphate of ʿUmar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uthman','en','{"name":"ʿUthmān ibn ʿAffān","when":"d. 35 AH","summary":"Dhū al-Nūrayn, the third Rightly Guided Caliph.","bio":"He married two daughters of the Prophet ﷺ, Ruqayya and then Umm Kulthūm. He emigrated to Abyssinia and then Madinah, equipped the Army of Hardship, and unified the copies of the Qurʾān into a single codex.","context":"He was martyred in the turmoil in 35 AH.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Companions"],["The Great Classes — Ibn Saʿd","Biographical entry: ʿUthmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('ali','en','{"name":"ʿAlī ibn Abī Ṭālib","when":"d. 40 AH","summary":"Cousin of the Prophet ﷺ, husband of Fāṭima and the fourth Rightly Guided Caliph.","bio":"He grew up in the household of the Prophet ﷺ and accepted Islam young. He slept in his bed on the night of the Hijra and returned the trusts, and witnessed the battles except Tabūk.","context":"He was known for knowledge, courage and judgment.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Companions"],["The Prophetic Biography — Ibn Hishām","ʿAlī sleeping in the Prophet’s bed"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aisha','en','{"name":"ʿĀʾisha bint Abī Bakr","when":"d. 58 AH","summary":"Mother of the Believers, among the Companions with the most narrations and jurisprudence.","bio":"The Prophet ﷺ married her in Makkah and consummated the marriage in Madinah. She narrated more than two thousand hadiths, and senior Companions used to ask her.","context":"The Prophet ﷺ died in her house and was buried in it.","sources":[["The Great Classes — Ibn Saʿd","Biographical entry: ʿĀʾisha"],["Sahih al-Bukhari","Book of the Virtues of the Companions"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('bilal','en','{"name":"Bilāl ibn Rabāḥ","when":"d. c. 20 AH","summary":"The first muezzin in Islam, known for his steadfastness under torture.","disputed":"The year and place of his death are disputed among the biographical sources (Damascus or Aleppo).","bio":"An Abyssinian slave of Umayya ibn Khalaf, tortured for his Islam, he said “One, One (Aḥad, Aḥad)”; Abū Bakr bought him and freed him.","context":"He gave the call to prayer on the day of the Conquest of Makkah from atop the Kaʿba.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the torture of Bilāl"],["Sahih al-Bukhari","Book of the Virtues of the Anṣār"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hamza','en','{"name":"Ḥamza ibn ʿAbd al-Muṭṭalib","when":"d. 3 AH","summary":"Uncle of the Prophet ﷺ and Lion of God, the master of the martyrs.","bio":"He accepted Islam in the second year of the mission and the Muslims were strengthened through him. He distinguished himself at Badr and was martyred at Uḥud.","context":"Waḥshī ibn Ḥarb killed him at the command of Hind bint ʿUtba.","sources":[["Sahih al-Bukhari","Book of Military Expeditions – The killing of Ḥamza"],["The Prophetic Biography — Ibn Hishām","The Battle of Uḥud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abutalib','en','{"name":"Abū Ṭālib ibn ʿAbd al-Muṭṭalib","when":"d. 619 CE","summary":"Uncle of the Prophet ﷺ, his guardian and protector against Quraysh.","bio":"He took the Prophet ﷺ in after his grandfather and protected him from the harm of Quraysh for ten years after the mission, but he died on the religion of his people.","context":"It is reported in the two Ṣaḥīḥs that he did not utter the declaration of faith at his death.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Anṣār – The story of Abū Ṭālib"],["The Prophetic Biography — Ibn Hishām","The death of Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('najashi','en','{"name":"The Negus Aṣḥama","when":"d. 9 AH","summary":"The just king of Abyssinia who gave refuge to the emigrants.","bio":"He listened to Sūrat Maryam from Jaʿfar ibn Abī Ṭālib and wept, refused to hand the Muslims over to Quraysh, and accepted Islam.","context":"The Prophet ﷺ prayed the funeral prayer for him in absentia when he died.","sources":[["Sahih al-Bukhari","Book of Funerals – Prayer for the Negus"],["The Prophetic Biography — Ibn Hishām","Account of the emigration to Abyssinia"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('musab','en','{"name":"Muṣʿab ibn ʿUmayr","when":"d. 3 AH","summary":"The first ambassador in Islam, sent by the Prophet ﷺ to teach the people of Madinah.","bio":"A pampered young man of Makkah who gave up comfort for his religion. Many of the Anṣār accepted Islam at his hand, among them Usayd ibn Ḥuḍayr and Saʿd ibn Muʿādh.","context":"He carried the Muslims’ banner at Uḥud and was martyred.","sources":[["Sahih al-Bukhari","Book of Military Expeditions – Battle of Uḥud"],["The Prophetic Biography — Ibn Hishām","Account of Muṣʿab"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('salman','en','{"name":"Salmān al-Fārisī","when":"d. c. 35 AH","summary":"The seeker of truth from Persia and the adviser of the Trench.","disputed":"His age at death is very much disputed among the reports.","bio":"He travelled from Persia seeking the truth until he reached Madinah and accepted Islam. He proposed digging the trench.","context":"The Prophet ﷺ said: “Salmān is one of us, the people of the House.”","sources":[["The Prophetic Biography — Ibn Hishām","Account of Salmān"],["The Great Classes — Ibn Saʿd","Biographical entry: Salmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khalid','en','{"name":"Khālid ibn al-Walīd","when":"d. 21 AH","summary":"The Drawn Sword of God, a great military commander.","bio":"One of the horsemen of Quraysh who led the encirclement at Uḥud, then accepted Islam before the Conquest, witnessed Mūta and led armies after the Prophet ﷺ.","context":"The Prophet ﷺ named him the Sword of God.","sources":[["Sahih al-Bukhari","Book of Military Expeditions – Battle of Mūta"],["The Beginning and the End — Ibn Kathīr","Biographical entry: Khālid"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abdurrahman','en','{"name":"ʿAbd al-Raḥmān ibn ʿAwf","when":"d. 32 AH","summary":"One of the ten promised Paradise, and the trustworthy merchant among the Companions.","bio":"He emigrated twice, and the Prophet ﷺ paired him in brotherhood with Saʿd ibn al-Rabīʿ, but he refused his brother’s wealth and said: “Show me the market.”","context":"He gave a great fortune in charity in the way of God.","sources":[["Sahih al-Bukhari","Book of the Virtues of the Anṣār – The brotherhood"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('arabia_pre','en','{"name":"Arabia before the Prophet’s birth","when":"Before 570 CE","summary":"The tribal society of Arabia and the standing of Quraysh and Makkah before the Prophet’s ﷺ birth.","bio":"Life in Arabia rested on tribe, trade and caravans; Quraysh looked after the Sacred House in Makkah, and idol worship was widespread around the Kaʿba. Jews and Christians lived in some of the peninsula’s towns and borderlands, and some Arabs who rejected idol worship were known as ḥanīfs.","context":"Sūrat Quraysh refers to the winter and summer journeys for which Quraysh were known.","sources":[["The Prophetic Biography — Ibn Hishām","Account of ʿAmr ibn Luḥayy and idol worship"],["The Noble Qurʾān","Sūrat Quraysh"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('childhood','en','{"name":"Childhood and orphanhood","when":"570 – about 578 CE","summary":"The Prophet ﷺ grew up an orphan, between his nursing among Banū Saʿd and the care of his grandfather and then his uncle.","bio":"He was nursed among Banū Saʿd by Ḥalīma al-Saʿdiyya, then returned to his mother Āmina, who died at al-Abwāʾ on her way back from Madinah when he was about six; his grandfather ʿAbd al-Muṭṭalib then took care of him, followed by his uncle Abū Ṭālib.","context":"The biographies mention that he was about eight years old when his grandfather died.","disputed":"Reports differ on his age when his mother and grandfather died, and on the order of some events.","sources":[["The Prophetic Biography — Ibn Hishām","Account of his nursing among Banū Saʿd"],["The Prophetic Biography — Ibn Hishām","Account of Āmina’s death and the care of ʿAbd al-Muṭṭalib and Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('youth','en','{"name":"Youth and trustworthiness","when":"About 580 – 595 CE","summary":"His shepherding, his trading journeys and his reputation for truthfulness and trustworthiness before the mission.","bio":"He worked as a shepherd for the people of Makkah, travelled for trade, became known among his people as the truthful and trustworthy, and witnessed the Ḥilf al-Fuḍūl pact with his uncles.","context":"Some biographies mention a journey to al-Shām with his uncle Abū Ṭālib when he was young, and a meeting with the monk Baḥīrā.","disputed":"Reports differ on the details of the journey to al-Shām, on how firmly the Baḥīrā story is established, and on his age at the Ḥilf al-Fuḍūl.","sources":[["Sahih al-Bukhari","Book of Hiring, chapter: shepherding for a few qirāṭs"],["The Prophetic Biography — Ibn Hishām","Account of the Ḥilf al-Fuḍūl pact"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba_rebuild','en','{"name":"Quraysh rebuild the Kaʿba; the Prophet ﷺ is chosen as arbiter","when":"About 605 CE (some five years before the mission)","summary":"Quraysh renewed the Kaʿba and made the Prophet ﷺ arbiter over the placing of the Black Stone.","bio":"The tribes of Quraysh disagreed over who should place the Black Stone and agreed to accept the first person to enter; it was the Prophet ﷺ, who put the stone on a cloth, had all the tribes lift it together, and then set it in place with his own hand.","context":"In the biographical reports the Prophet ﷺ was about thirty-five years old.","disputed":"Reports differ on his age at the rebuilding of the Kaʿba; the best-known figure is about thirty-five.","sources":[["The Prophetic Biography — Ibn Hishām","Account of Quraysh’s rebuilding of the Kaʿba"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('secret_dawah','en','{"name":"The private call","when":"About 610 – 613 CE","summary":"The first years of the call, made privately among relatives and trusted people before it was made public.","bio":"The Prophet ﷺ called privately those he trusted; Khadīja, Abū Bakr, ʿAlī, Zayd ibn Ḥāritha and others followed him, and the Muslims kept their worship out of sight.","context":"The biographies mention that the house of al-Arqam ibn Abī al-Arqam was one of the places where Muslims met.","disputed":"The best-known view is that the private phase lasted about three years; reports differ on its length.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the beginning of the call and the first to accept Islam"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('persecution','en','{"name":"Persecution of the early Muslims","when":"From about 613 CE","summary":"The harm suffered by the Prophet ﷺ and by vulnerable Muslims after the call became public.","bio":"Many vulnerable Muslims were tortured and harmed, among them Bilāl ibn Rabāḥ; Abū Bakr bought a number of them and freed them, and the Prophet ﷺ himself faced harm and ridicule.","context":"This hardship led some Muslims to emigrate to Abyssinia.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the harm the Muslims suffered"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('boycott','en','{"name":"The boycott of the Valley of Abū Ṭālib","when":"About 616 – 619 CE (7th to 10th year of the mission)","summary":"The boycott of Banū Hāshim and Banū al-Muṭṭalib by Quraysh, who were confined to the valley.","bio":"Quraysh agreed to boycott Banū Hāshim and Banū al-Muṭṭalib in trade and marriage; the Prophet ﷺ and those with him took refuge in the valley of Abū Ṭālib for a time, until the pact was annulled.","context":"It was followed by the Year of Sorrow.","disputed":"Reports differ on when it began and how long it lasted: the best-known figure is about three years, and some say less.","sources":[["The Prophetic Biography — Ibn Hishām","Account of the pact document and the siege of the valley"],["The Beginning and the End — Ibn Kathīr","The siege of Banū Hāshim in the valley"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif_trip','en','{"name":"The journey to Ṭāʾif","when":"Shawwāl, 10th year of the mission – about 619 CE","summary":"The Prophet’s ﷺ journey to Ṭāʾif to call its people, after the deaths of Abū Ṭālib and Khadīja.","bio":"He set out with Zayd ibn Ḥāritha and offered Islam to the leaders of Thaqīf, who rejected him and set their foolish ones against him, so they threw stones at him; he then returned to Makkah under the protection of al-Muṭʿim ibn ʿAdī.","context":"The Ṣaḥīḥ contains ʿĀʾisha’s report about the hardest day the Prophet ﷺ faced, at Ṭāʾif.","sources":[["Sahih al-Bukhari","Book of the Beginning of Creation"],["The Prophetic Biography — Ibn Hishām","Account of his journey to Ṭāʾif"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khaybar','en','{"name":"The campaign of Khaybar","when":"Muḥarram 7 AH – 628 CE","summary":"The Muslims’ campaign against the fortresses of the Jews of Khaybar, north of Madinah, after the Treaty of al-Ḥudaybiya.","bio":"After returning from al-Ḥudaybiya the Prophet ﷺ marched to Khaybar, besieged and took its fortresses, and let its people keep working the land for half of the produce.","context":"The Ṣaḥīḥ reports that the Prophet ﷺ gave the banner to ʿAlī ibn Abī Ṭālib in this campaign.","disputed":"Reports differ on the month: the best-known view is Muḥarram of the seventh year; other months are also given.","sources":[["Sahih al-Bukhari","Book of the Campaigns, chapter: the campaign of Khaybar"],["The Prophetic Biography — Ibn Hishām","Account of the campaign of Khaybar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muta','en','{"name":"The Battle of Muʾta","when":"Jumādā al-Ūlā 8 AH – 629 CE","summary":"A battle between the Muslims and the Byzantine army and its allies on the edge of al-Shām, in which three Muslim commanders were martyred.","bio":"The Prophet ﷺ sent an army under Zayd ibn Ḥāritha, then Jaʿfar ibn Abī Ṭālib, then ʿAbd Allāh ibn Rawāḥa; all three were martyred, and Khālid ibn al-Walīd took the banner and brought the army back.","context":"In al-Bukhārī’s report the Prophet ﷺ called Khālid a sword among the swords of God on this occasion.","disputed":"Reports vary in the numbers given for the two armies and in how the outcome is described.","sources":[["Sahih al-Bukhari","Book of the Campaigns, chapter: the campaign of Muʾta in the land of al-Shām"],["The Prophetic Biography — Ibn Hishām","Account of the campaign of Muʾta"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hunayn','en','{"name":"The Battle of Ḥunayn","when":"Shawwāl 8 AH – 630 CE","summary":"The Muslims’ battle with Hawāzin and Thaqīf after the Conquest of Makkah.","bio":"The Muslims set out in a large army; the enemy took them by surprise in the valley of Ḥunayn and their ranks wavered, but the Prophet ﷺ and those with him stood firm, the Muslims rallied, and they prevailed.","context":"The Qurʾān refers to this day in Sūrat al-Tawba; the Muslims then proceeded to Ṭāʾif.","sources":[["Sahih al-Bukhari","Book of the Campaigns, chapter: the saying of God, “and on the day of Ḥunayn”"],["The Noble Qurʾān","Sūrat al-Tawba 9:25–26"],["The Prophetic Biography — Ibn Hishām","Account of the campaign of Ḥunayn"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('tabuk','en','{"name":"The expedition to Tabūk","when":"Rajab 9 AH – 630 CE","summary":"The Prophet’s ﷺ march with a large army towards Tabūk on the edge of al-Shām; no fighting took place.","bio":"The Prophet ﷺ set out in a time of hardship and heat to meet what he had heard of Byzantine gatherings; he reached Tabūk, stayed some days, and returned without fighting. His army was called the Army of Hardship.","context":"Three Companions stayed behind and were later forgiven.","disputed":"Reports vary on how long he stayed at Tabūk.","sources":[["Sahih al-Bukhari","Book of the Campaigns, chapter: the campaign of Tabūk"],["The Noble Qurʾān","Sūrat al-Tawba 9:117–118"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('illness','en','{"name":"The Prophet’s final illness","when":"Late Ṣafar – Rabīʿ al-Awwal 11 AH – 632 CE","summary":"The Prophet’s ﷺ last days of illness in the house of ʿĀʾisha until his death.","bio":"As his illness grew heavy he asked his wives’ permission to be cared for in ʿĀʾisha’s house, and they agreed; he told Abū Bakr to lead the people in prayer.","context":"The preparation of the army of Usāma ibn Zayd preceded his illness.","disputed":"Reports differ on when the illness began and how long it lasted: the best-known figure is about ten days, and some say thirteen.","sources":[["Sahih al-Bukhari","Book of the Campaigns, chapter: the illness and death of the Prophet ﷺ"],["Sahih al-Bukhari","Book of the Call to Prayer, chapter: people of knowledge and merit have most right to lead the prayer"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muhammad','es','{"name":"El Profeta Muhammad ﷺ","when":"570 – 632","summary":"Sello de los profetas y mensajeros, Muhammad ibn ʿAbd Allāh ibn ʿAbd al-Muṭṭalib, de los Banū Hāshim, de Quraysh.","bio":"Nació en La Meca en el Año del Elefante y creció huérfano; entre su gente era conocido como el Veraz, el Digno de confianza. Fue enviado a los cuarenta años, llamó a la unicidad de Dios durante veintitrés años y luego murió en Medina al-Munawwara.","context":"Vivió en un entorno tribal de la península arábiga dominado por la idolatría; su mensaje trajo el monoteísmo y la construcción de una sociedad nueva basada en la justicia y la fraternidad.","sources":[["La Biografía profética — Ibn Hishām","Partes 1 y 2"],["Sahih al-Bujari","Libro de los méritos"],["El Néctar sellado — al-Mubārakfūrī","Pasajes diversos"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('companions','es','{"name":"Los Compañeros","when":"610 – 632","summary":"Quienes conocieron al Profeta ﷺ creyendo en él y murieron en esa fe.","bio":"Definición de Compañero según la mayoría de los especialistas en hadices: quien conoció al Profeta ﷺ creyendo en él y murió musulmán. Llevaron el mensaje, transmitieron la Sunna y fundaron el Estado tras él.","context":"Se dividen en varios rangos: los primeros creyentes, los emigrados a Abisinia, los de Badr, quienes prestaron el juramento de Ridwān y quienes abrazaron el islam el año de la Conquista.","sources":[["Las Grandes Generaciones — Ibn Saʿd","Introducción a los Ṭabaqāt"],["al-Iṣāba fī Tamyīz al-Ṣaḥāba — Ibn Ḥajar","Introducción"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('makkah','es','{"name":"La Meca (al-Mukarrama)","when":"Nacimiento y crianza del Profeta ﷺ","summary":"Lugar de nacimiento del Profeta ﷺ, tierra de la revelación y sede de la noble Kaaba.","bio":"Ciudad en un valle sin cultivos en el Hiyaz, que alberga la Casa Sagrada; era un centro comercial y religioso dirigido por Quraysh.","context":"El Profeta ﷺ pasó allí cincuenta y tres años antes de la Hégira y la conquistó en 8 AH.","sources":[["La Biografía profética — Ibn Hishām","Relato de la construcción de la Kaaba"],["El Noble Corán","Sura al-Balad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madinah','es','{"name":"Medina (al-Munawwara)","when":"Desde 622","summary":"Ciudad de la Hégira, capital del primer Estado islámico y lugar de sepultura del Profeta ﷺ.","bio":"Se llamaba Yazrib y la habitaban los Aws, los Jazray y tribus judías. Tras la Hégira, el Profeta ﷺ cambió su nombre por Ṭayba y al-Madīna.","context":"Alberga la Mezquita del Profeta; de ella partieron las expediciones y en ella se construyó la comunidad musulmana.","sources":[["La Biografía profética — Ibn Hishām","Relato de la Hégira"],["Sahih al-Bujari","Libro de las virtudes de Medina"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hira','es','{"name":"La cueva de Hira","when":"Jabal al-Nur – La Meca","summary":"La cueva donde el Profeta ﷺ se retiraba a adorar y donde descendió la primera revelación.","bio":"Pequeña cueva en el Jabal al-Nūr, a unas tres millas de La Meca, donde el Profeta ﷺ se retiraba a adorar durante un número de noches.","context":"En ella se revelaron los primeros versículos de la sura al-ʿAlaq.","sources":[["Sahih al-Bujari","Libro del comienzo de la revelación"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba','es','{"name":"La noble Kaaba","when":"Quibla de los musulmanes","summary":"La Casa Sagrada cuyos cimientos levantaron Ibrahim e Ismaʿil, la paz sea con ellos.","bio":"Quraysh la reconstruyó unos cinco años antes de la misión; el Profeta ﷺ participó en ello y arbitró la colocación de la Piedra Negra.","context":"El Profeta ﷺ la purificó de ídolos el día de la Conquista de La Meca.","sources":[["La Biografía profética — Ibn Hishām","Relato de la reconstrucción de la Kaaba por Quraysh"],["El Noble Corán","Sura al-Baqara 2:127"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif','es','{"name":"Taif","when":"Décimo año de la misión","summary":"La ciudad a la que el Profeta ﷺ acudió para llamar a su gente, que lo rechazó.","bio":"El Profeta ﷺ salió hacia ella con Zayd ibn Ḥāritha tras la muerte de Abū Ṭālib y de Jadīya; sus insensatos le hicieron daño y le arrojaron piedras.","context":"Se transmite en el Ṣaḥīḥ que Yibrīl le ofreció juntar sobre ellos las dos montañas, y él respondió: «Más bien espero que Dios haga salir de sus entrañas a quienes adoren a Dios solo».","sources":[["Sahih al-Bujari","Libro del comienzo de la creación"],["Sahih Muslim","Libro del yihad y las expediciones"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha','es','{"name":"Abisinia","when":"Dos emigraciones, 615 y 616","summary":"La tierra a la que emigraron los primeros musulmanes bajo la protección del justo Negus.","bio":"El Profeta ﷺ dijo a los musulmanes: «Allí hay un rey junto al cual nadie es oprimido». Permanecieron allí seguros en su religión.","context":"Entre los más destacados que emigraron allí estaban ʿUthmān ibn ʿAffān, su esposa Ruqayya y Jaʿfar ibn Abī Ṭālib.","sources":[["La Biografía profética — Ibn Hishām","Relato de la emigración a tierra de Abisinia"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('elephant','es','{"name":"El Año del Elefante","when":"h. 570","summary":"El intento de Abraha el abisinio de destruir la Kaaba y la aniquilación de su ejército.","bio":"Abraha condujo hacia La Meca un ejército con elefantes, y Dios envió contra él bandadas de pájaros. En ese año nació el Profeta ﷺ.","context":"La sura al-Fīl lo menciona, y los árabes lo usaban para fechar los acontecimientos.","sources":[["El Noble Corán","Sura al-Fīl"],["La Biografía profética — Ibn Hishām","Relato de la gente del Elefante"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('birth','es','{"name":"Nacimiento del Profeta ﷺ","when":"12 de Rabīʿ al-Awwal – Año del Elefante","summary":"El nacimiento de Muhammad ibn ʿAbd Allāh en La Meca, huérfano de padre.","disputed":"El día del mes es discutido: el más conocido es el 12 de Rabīʿ al-Awwal; también se mencionan el 2, el 8 o el 9. Los astrónomos contemporáneos prefieren el 9 de Rabīʿ al-Awwal.","bio":"Nació tras la muerte de su padre ʿAbd Allāh; lo tomaron a su cargo su abuelo ʿAbd al-Muṭṭalib y luego su tío Abū Ṭālib. Fue puesto a criar entre los Banū Saʿd, con Ḥalīma al-Saʿdiyya.","context":"Lo acordado es que nació un lunes, en el Año del Elefante.","sources":[["La Biografía profética — Ibn Hishām","Relato del nacimiento del Mensajero de Dios ﷺ"],["Sahih Muslim","Libro del ayuno – El ayuno del lunes"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('marriage','es','{"name":"Matrimonio con Jadīya","when":"h. 595","summary":"El matrimonio del Profeta ﷺ con Jadīya bint Juwaylid cuando tenía veinticinco años.","disputed":"La edad de Jadīya al casarse: la opinión más conocida es cuarenta años; se mencionan otras.","bio":"El Profeta ﷺ trabajó en el comercio de ella hacia al-Shām; ella vio su honradez y le propuso matrimonio. Le dio sus hijos, salvo Ibrāhīm.","context":"Fue la primera en creer en él y su apoyo en los años más duros de la llamada.","sources":[["La Biografía profética — Ibn Hishām","Relato del matrimonio con Jadīya"],["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: Jadīya"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('revelation','es','{"name":"La Revelación","when":"Ramadán – h. 610","summary":"Yibrīl trajo los primeros versículos del Corán en la cueva de Hira: «Lee en el nombre de tu Señor que creó».","disputed":"El día de la primera revelación en Ramadán es discutido (17, 21 o 24); para muchos lo más probable es la Noche del Destino.","bio":"El Profeta ﷺ tenía cuarenta años cuando vino Yibrīl, lo abrazó y le dijo: «Lee». Volvió junto a Jadīya con el corazón tembloroso; ella lo tranquilizó y lo llevó ante Waraqa ibn Nawfal.","context":"Luego la revelación se interrumpió durante un tiempo y se reveló la sura al-Muddaththir con la orden de advertir.","sources":[["Sahih al-Bujari","Libro del comienzo de la revelación, capítulo: cómo comenzó la revelación"],["El Noble Corán","Sura al-ʿAlaq"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('dawah','es','{"name":"La predicación pública","when":"h. 613","summary":"Tras tres años de predicación en secreto, Dios ordenó a Su Profeta proclamar el mensaje abiertamente.","bio":"El Profeta ﷺ subió al monte al-Ṣafā y llamó a Quraysh, y se reveló la palabra del Altísimo (en su sentido): «Y advierte a tus parientes más cercanos».","context":"Después de eso se intensificó el daño que los politeístas causaban a los musulmanes.","sources":[["Sahih al-Bujari","Comentario de la sura al-Masad"],["La Biografía profética — Ibn Hishām","Relato de la llamada pública"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('habasha_hijra','es','{"name":"La emigración a Abisinia","when":"Quinto año de la misión","summary":"Los musulmanes huyeron con su fe de la persecución de Quraysh hacia el Negus.","bio":"Partió el primer grupo, de unos doce hombres y cuatro mujeres, y luego los siguieron grupos mayores. Quraysh envió una delegación al Negus, que la rechazó.","context":"Los libros de biografías conservaron el diálogo entre Jaʿfar ibn Abī Ṭālib y el Negus.","sources":[["La Biografía profética — Ibn Hishām","Relato de la emigración a Abisinia"],["El Principio y el Fin — Ibn Kazīr","La primera emigración"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('sorrow','es','{"name":"El Año de la Tristeza","when":"Décimo año de la misión – 619","summary":"La muerte de Abū Ṭālib y luego de Jadīya, y la salida del Profeta ﷺ hacia Taif.","bio":"El Profeta ﷺ perdió a su protector y a su esposa en poco tiempo, y se agravó el daño que le hacía Quraysh.","context":"Los biógrafos le dieron ese nombre.","sources":[["La Biografía profética — Ibn Hishām","La muerte de Abū Ṭālib y de Jadīya"],["El Principio y el Fin — Ibn Kazīr","El Año de la Tristeza"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('isra','es','{"name":"El Viaje Nocturno y la Ascensión","when":"Antes de la Hégira","summary":"El viaje nocturno del Profeta ﷺ desde la Mezquita Sagrada hasta al-Aqṣā y su ascenso a través de los cielos.","disputed":"Que el viaje tuvo lugar es seguro, pero su fecha es discutida; ninguna prueba sólida respalda la conocida noche del 27 de Rajab.","bio":"En él se prescribieron las cinco oraciones, y el Profeta ﷺ vio algunos de los mayores signos de su Señor.","context":"El Corán lo menciona al comienzo de la sura al-Isrāʾ y en la sura al-Najm.","sources":[["El Noble Corán","Sura al-Isrāʾ 17:1"],["Sahih al-Bujari","Libro de los méritos de los Ansār – Capítulo sobre el Miʿrāj"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aqaba','es','{"name":"Los dos juramentos de al-ʿAqaba","when":"621 – 622","summary":"Una delegación de los Ansār juró apoyar y proteger al Profeta ﷺ como protegen a sus mujeres e hijos.","bio":"En la primera ʿAqaba juraron doce, y en la segunda setenta y tres hombres y dos mujeres. El Profeta ﷺ envió a Muṣʿab ibn ʿUmayr como maestro.","context":"Preparó directamente la Hégira a Medina.","sources":[["La Biografía profética — Ibn Hishām","Relato del primer y segundo juramento de al-ʿAqaba"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hijra','es','{"name":"La Hégira a Medina","when":"1 AH – 622","summary":"El Profeta ﷺ se trasladó con Abū Bakr de La Meca a Medina: comienzo del calendario hegírico.","bio":"Salieron de noche y se ocultaron en la cueva de Zawr durante tres días; luego viajaron con un guía hasta Qubāʾ y después Medina. Su gente lo recibió con alegría.","context":"Se usó para fechar en tiempos de ʿUmar ibn al-Jaṭṭāb, que Dios esté complacido con él.","sources":[["Sahih al-Bujari","Libro de los méritos de los Ansār – Capítulo sobre la Hégira del Profeta ﷺ"],["La Biografía profética — Ibn Hishām","Relato de la Hégira"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('madina_state','es','{"name":"La construcción del Estado islámico","when":"1 AH – 622/623","summary":"Construcción de la Mezquita del Profeta, hermandad entre Muhājirūn y Ansār y redacción de la Carta de Medina.","disputed":"La Carta es transmitida por Ibn Isḥāq y otros, pero su redacción y su reunión en un solo documento son objeto de debate entre los investigadores.","bio":"El Profeta ﷺ comenzó construyendo la mezquita, luego estableció la hermandad entre los Muhājirūn y los Ansār, y reguló las relaciones entre los habitantes de Medina mediante un documento conocido como la Ṣaḥīfa (Carta) de Medina.","context":"Estos pasos formaron el núcleo de la comunidad y del Estado.","sources":[["La Biografía profética — Ibn Hishām","Relato de la construcción de la mezquita, la hermandad y la Carta"],["Sahih al-Bujari","Libro de los méritos de los Ansār – La hermandad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('badr','es','{"name":"La batalla de Badr","when":"17 de Ramadán 2 AH – 624","summary":"Primera batalla decisiva entre los musulmanes y Quraysh, ganada por los musulmanes.","bio":"El Profeta ﷺ salió con unos trescientos trece hombres y se enfrentaron a unos mil de Quraysh; Dios les dio la victoria a pesar de su escaso número y equipo.","context":"El Corán lo llamó el Día del Criterio (Yawm al-Furqān).","sources":[["El Noble Corán","Sura al-Anfāl"],["Sahih al-Bujari","Libro de las expediciones – Batalla de Badr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uhud','es','{"name":"La batalla de Uhud","when":"Shawwāl 3 AH – 625","summary":"Batalla junto al monte Uhud en la que murieron mártires Hamza y varios Compañeros.","bio":"Comenzó con una victoria de los musulmanes; luego los arqueros desobedecieron la orden del Profeta ﷺ y Jālid ibn al-Walīd rodeó con la caballería de Quraysh.","context":"La sura Āl ʿImrān habla de ella.","sources":[["El Noble Corán","Sura Āl ʿImrān 3:121–179"],["Sahih al-Bujari","Libro de las expediciones – Batalla de Uhud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khandaq','es','{"name":"La batalla del Foso","when":"Shawwāl 5 AH – 627","summary":"Los coaligados sitiaron Medina; el foso se cavó por consejo de Salmān al-Fārisī.","disputed":"Los relatos discrepan sobre el año de la campaña: el más conocido es el 5 H. y algunos dicen el 4.","bio":"Los coaligados sitiaron Medina durante cerca de un mes, y Dios envió contra ellos un viento y soldados, y se marcharon decepcionados.","context":"Se revelaron sobre ella versículos de la sura al-Aḥzāb.","sources":[["El Noble Corán","Sura al-Aḥzāb"],["La Biografía profética — Ibn Hishām","La batalla del Foso"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hudaybiyyah','es','{"name":"El tratado de al-Hudaybiya","when":"Dhū al-Qaʿda 6 AH – 628","summary":"Tratado entre el Profeta ﷺ y Quraysh para detener la guerra durante diez años.","bio":"El Profeta ﷺ salió con la intención de hacer la ʿumra y Quraysh se lo impidió; acordaron una tregua con la condición de que volviera al año siguiente. El tratado pareció pesado a algunos Compañeros, pero Dios lo llamó una victoria.","context":"Le siguió el juramento de Ridwān bajo el árbol.","sources":[["El Noble Corán","Sura al-Fatḥ"],["Sahih al-Bujari","Libro de las condiciones – Las condiciones en el yihad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('fath','es','{"name":"La conquista de La Meca","when":"Ramadán 8 AH – 630","summary":"El Profeta ﷺ entró en La Meca con diez mil Compañeros y purificó la Kaaba de ídolos.","bio":"Quraysh rompió el tratado, y el Profeta ﷺ marchó contra ella; entró con humildad y perdonó a su gente, diciendo: «Id, que sois los liberados».","context":"Después, la gente entró en la religión de Dios en masa.","sources":[["El Noble Corán","Sura al-Naṣr"],["Sahih al-Bujari","Libro de las expediciones – Conquista de La Meca"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('farewell','es','{"name":"La Peregrinación de Despedida","when":"10 AH – 632","summary":"La única peregrinación del Profeta ﷺ, en la que pronunció el gran sermón de ʿArafa.","bio":"Pronunció en ʿArafa un sermón que afirmaba la inviolabilidad de la sangre y de los bienes y los derechos de las mujeres, y se reveló la palabra del Altísimo (en su sentido): «Hoy os he perfeccionado vuestra religión».","context":"Estaban con él más de cien mil Compañeros.","sources":[["Sahih Muslim","Libro del Hayy – La peregrinación del Profeta ﷺ"],["El Noble Corán","Sura al-Māʾida 5:3"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('death','es','{"name":"Muerte del Profeta ﷺ","when":"Rabīʿ al-Awwal 11 AH – 632","summary":"El Profeta ﷺ partió hacia el Compañero Supremo en Medina, a los sesenta y tres años.","disputed":"La opinión más extendida es que murió el lunes 12 de Rabīʿ al-Awwal; también se menciona el 2 de Rabīʿ al-Awwal.","bio":"Estuvo enfermo varios días y ordenó a Abū Bakr que dirigiera la oración de la gente; murió en la casa de ʿĀʾisha, que Dios esté complacido con ella, y fue enterrado en ella.","context":"Abū Bakr asumió el califato después de él.","sources":[["Sahih al-Bujari","Libro de las expediciones – Capítulo sobre la enfermedad y muerte del Profeta ﷺ"],["La Biografía profética — Ibn Hishām","Relato de la muerte del Mensajero de Dios ﷺ"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khadija','es','{"name":"Jadīya bint Juwaylid","when":"m. 619","summary":"Primera Madre de los creyentes y primera en creer en el Profeta ﷺ.","bio":"Comerciante qurayshí de riqueza y nobleza; el Profeta ﷺ se casó con ella y no tomó otra esposa mientras ella vivió. Apoyó la llamada con sus bienes y con su persona.","context":"Murió tres años antes de la Hégira, y el Profeta ﷺ la recordaba con lealtad.","sources":[["Sahih al-Bujari","Libro de los méritos de los Ansār – El matrimonio del Profeta ﷺ con Jadīya"],["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: Jadīya"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abubakr','es','{"name":"Abū Bakr al-Ṣiddīq","when":"m. 13 AH","summary":"Compañero del Profeta ﷺ en la cueva y primero de los califas bien guiados.","bio":"ʿAbd Allāh ibn Abī Quḥāfa al-Taymī, el primer hombre en abrazar el islam según el relato más conocido; liberó a los oprimidos y acompañó al Profeta ﷺ en la Hégira. Asumió el califato tras la muerte del Profeta ﷺ.","context":"Combatió a los apóstatas e hizo reunir el Corán en páginas por consejo de ʿUmar.","sources":[["Sahih al-Bujari","Libro de las virtudes de los Compañeros"],["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: Abū Bakr"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('umar','es','{"name":"ʿUmar ibn al-Jaṭṭāb","when":"m. 23 AH","summary":"Al-Fārūq, segundo califa bien guiado; su conversión fortaleció el islam.","bio":"De los Banū ʿAdī, era conocido por su firmeza en la verdad y por su justicia. Abrazó el islam en La Meca, participó en todas las batallas y ejerció el califato diez años, en los que se conquistaron al-Shām, Irak y Egipto.","context":"Estableció el calendario hegírico e instituyó los registros (dīwāns).","sources":[["Sahih al-Bujari","Libro de las virtudes de los Compañeros"],["El Principio y el Fin — Ibn Kazīr","El califato de ʿUmar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('uthman','es','{"name":"ʿUthmān ibn ʿAffān","when":"m. 35 AH","summary":"Dhū al-Nūrayn, tercer califa bien guiado.","bio":"Se casó con dos hijas del Profeta ﷺ, Ruqayya y luego Umm Kulthūm. Emigró a Abisinia y luego a Medina, equipó el ejército de la Penuria (ʿUsra) y unificó las copias del Corán en un solo códice.","context":"Fue martirizado en las turbulencias del año 35 AH.","sources":[["Sahih al-Bujari","Libro de las virtudes de los Compañeros"],["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: ʿUthmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('ali','es','{"name":"ʿAlī ibn Abī Ṭālib","when":"m. 40 AH","summary":"Primo del Profeta ﷺ, esposo de Fāṭima y cuarto califa bien guiado.","bio":"Creció en la casa del Profeta ﷺ y abrazó el islam siendo joven. Durmió en su lecho la noche de la Hégira y devolvió los depósitos, y participó en las batallas salvo Tabūk.","context":"Era conocido por su ciencia, su valentía y su juicio.","sources":[["Sahih al-Bujari","Libro de las virtudes de los Compañeros"],["La Biografía profética — Ibn Hishām","ʿAlī durmiendo en el lecho del Profeta"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('aisha','es','{"name":"ʿĀʾisha bint Abī Bakr","when":"m. 58 AH","summary":"Madre de los creyentes, entre los Compañeros con más transmisiones y jurisprudencia.","bio":"El Profeta ﷺ se casó con ella en La Meca y consumó el matrimonio en Medina. Transmitió más de dos mil hadices y los grandes Compañeros le consultaban.","context":"El Profeta ﷺ murió en su casa y fue enterrado en ella.","sources":[["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: ʿĀʾisha"],["Sahih al-Bujari","Libro de las virtudes de los Compañeros"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('bilal','es','{"name":"Bilāl ibn Rabāḥ","when":"m. h. 20 AH","summary":"El primer almuédano del islam, conocido por su firmeza bajo la tortura.","disputed":"El año y el lugar de su muerte son discutidos en las fuentes biográficas (Damasco o Alepo).","bio":"Esclavo abisinio de Umayya ibn Jalaf, torturado por su islam, decía «Uno, Uno (Aḥad, Aḥad)»; Abū Bakr lo compró y lo liberó.","context":"Hizo la llamada a la oración el día de la Conquista de La Meca desde lo alto de la Kaaba.","sources":[["La Biografía profética — Ibn Hishām","Relato de la tortura de Bilāl"],["Sahih al-Bujari","Libro de los méritos de los Ansār"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hamza','es','{"name":"Hamza ibn ʿAbd al-Muṭṭalib","when":"m. 3 AH","summary":"Tío del Profeta ﷺ y León de Dios, señor de los mártires.","bio":"Abrazó el islam en el segundo año de la misión y los musulmanes se fortalecieron con él. Se distinguió en Badr y fue martirizado en Uhud.","context":"Lo mató Waḥshī ibn Ḥarb por orden de Hind bint ʿUtba.","sources":[["Sahih al-Bujari","Libro de las expediciones – La muerte de Hamza"],["La Biografía profética — Ibn Hishām","La batalla de Uhud"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abutalib','es','{"name":"Abū Ṭālib ibn ʿAbd al-Muṭṭalib","when":"m. 619","summary":"Tío del Profeta ﷺ, su tutor y protector frente a Quraysh.","bio":"Se hizo cargo del Profeta ﷺ tras su abuelo y lo protegió del daño de Quraysh durante diez años después de la misión, pero murió en la religión de su pueblo.","context":"Se transmite en los dos Ṣaḥīḥ que no pronunció la profesión de fe al morir.","sources":[["Sahih al-Bujari","Libro de los méritos de los Ansār – La historia de Abū Ṭālib"],["La Biografía profética — Ibn Hishām","La muerte de Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('najashi','es','{"name":"El Negus Aṣḥama","when":"m. 9 AH","summary":"El justo rey de Abisinia que dio refugio a los emigrados.","bio":"Escuchó la sura Maryam recitada por Jaʿfar ibn Abī Ṭālib y lloró, se negó a entregar a los musulmanes a Quraysh y abrazó el islam.","context":"El Profeta ﷺ rezó por él la oración fúnebre en ausencia cuando murió.","sources":[["Sahih al-Bujari","Libro de los funerales – La oración por el Negus"],["La Biografía profética — Ibn Hishām","Relato de la emigración a Abisinia"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('musab','es','{"name":"Muṣʿab ibn ʿUmayr","when":"m. 3 AH","summary":"El primer embajador del islam, enviado por el Profeta ﷺ para instruir a la gente de Medina.","bio":"Joven mimado de La Meca que abandonó la comodidad por su religión. Muchos de los Ansār abrazaron el islam por su mano, entre ellos Usayd ibn Ḥuḍayr y Saʿd ibn Muʿādh.","context":"Llevó el estandarte de los musulmanes en Uhud y fue martirizado.","sources":[["Sahih al-Bujari","Libro de las expediciones – Batalla de Uhud"],["La Biografía profética — Ibn Hishām","Relato de Muṣʿab"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('salman','es','{"name":"Salmān al-Fārisī","when":"m. h. 35 AH","summary":"El buscador de la verdad venido de Persia y consejero de la batalla del Foso.","disputed":"Su edad al morir es muy discutida según los relatos.","bio":"Viajó desde Persia en busca de la verdad hasta llegar a Medina, donde abrazó el islam. Propuso cavar el foso.","context":"El Profeta ﷺ dijo: «Salmān es de los nuestros, la gente de la Casa».","sources":[["La Biografía profética — Ibn Hishām","Relato de Salmān"],["Las Grandes Generaciones — Ibn Saʿd","Entrada biográfica: Salmān"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khalid','es','{"name":"Jālid ibn al-Walīd","when":"m. 21 AH","summary":"La Espada Desenvainada de Dios, gran jefe militar.","bio":"Uno de los jinetes de Quraysh, dirigió el movimiento envolvente en Uhud; luego abrazó el islam antes de la Conquista, participó en Mūta y mandó ejércitos después del Profeta ﷺ.","context":"El Profeta ﷺ lo llamó la Espada de Dios.","sources":[["Sahih al-Bujari","Libro de las expediciones – Batalla de Mūta"],["El Principio y el Fin — Ibn Kazīr","Entrada biográfica: Jālid"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('abdurrahman','es','{"name":"ʿAbd al-Raḥmān ibn ʿAwf","when":"m. 32 AH","summary":"Uno de los diez a quienes se prometió el Paraíso y el mercader íntegro entre los Compañeros.","bio":"Emigró dos veces, y el Profeta ﷺ estableció la hermandad entre él y Saʿd ibn al-Rabīʿ, pero rechazó los bienes de su hermano y dijo: «Mostradme el mercado».","context":"Dio una gran fortuna en caridad en el camino de Dios.","sources":[["Sahih al-Bujari","Libro de los méritos de los Ansār – La hermandad"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('arabia_pre','es','{"name":"Arabia antes del nacimiento del Profeta ﷺ","when":"Antes del 570","summary":"La sociedad tribal de Arabia y la posición de los Quraysh y La Meca antes del nacimiento del Profeta ﷺ.","bio":"La vida en Arabia se basaba en la tribu, el comercio y las caravanas; los Quraysh cuidaban la Casa Sagrada en La Meca y el culto a los ídolos estaba extendido alrededor de la Kaaba. Judíos y cristianos vivían en algunas ciudades y fronteras de la península, y algunos árabes que rechazaban los ídolos eran conocidos como ḥanīfs.","context":"La sura Quraysh alude a los viajes de invierno y verano por los que eran conocidos los Quraysh.","sources":[["La Biografía profética — Ibn Hishām","Relato sobre ʿAmr ibn Luḥayy y el culto a los ídolos"],["El Noble Corán","Sura Quraysh"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('childhood','es','{"name":"Infancia y orfandad","when":"570 – hacia el 578","summary":"El Profeta ﷺ creció huérfano, entre su crianza con los Banū Saʿd y el cuidado de su abuelo y luego de su tío.","bio":"Fue criado entre los Banū Saʿd por Ḥalīma al-Saʿdiyya y luego volvió con su madre Āmina, que murió en al-Abwāʾ de regreso de Medina cuando él tenía unos seis años; su abuelo ʿAbd al-Muṭṭalib se hizo cargo de él y después su tío Abū Ṭālib.","context":"Las biografías mencionan que tenía unos ocho años cuando murió su abuelo.","disputed":"Los relatos discrepan sobre su edad cuando murieron su madre y su abuelo, y sobre el orden de algunos sucesos.","sources":[["La Biografía profética — Ibn Hishām","Relato de su crianza entre los Banū Saʿd"],["La Biografía profética — Ibn Hishām","Relato de la muerte de Āmina y del cuidado de ʿAbd al-Muṭṭalib y Abū Ṭālib"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('youth','es','{"name":"Juventud y honradez","when":"Hacia 580 – 595","summary":"Su pastoreo, sus viajes comerciales y su fama de sinceridad y honradez antes de la misión.","bio":"Fue pastor para la gente de La Meca, viajó por comercio, se hizo conocido entre su pueblo como el veraz y el honrado, y presenció con sus tíos el pacto de al-Fuḍūl.","context":"Algunas biografías mencionan un viaje a al-Shām con su tío Abū Ṭālib de joven y un encuentro con el monje Baḥīrā.","disputed":"Los relatos discrepan sobre los detalles del viaje a al-Shām, sobre la solidez del relato de Baḥīrā y sobre su edad en el pacto de al-Fuḍūl.","sources":[["Sahih al-Bujari","Libro del alquiler, capítulo: pastorear por unos pocos qirāṭ"],["La Biografía profética — Ibn Hishām","Relato del pacto de al-Fuḍūl"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('kaaba_rebuild','es','{"name":"Los Quraysh reconstruyen la Kaaba; el Profeta ﷺ es elegido árbitro","when":"Hacia el 605 (unos cinco años antes de la misión)","summary":"Los Quraysh renovaron la Kaaba y eligieron al Profeta ﷺ como árbitro sobre la colocación de la Piedra Negra.","bio":"Las tribus de los Quraysh discutieron sobre quién colocaría la Piedra Negra y acordaron aceptar al primero que entrara; fue el Profeta ﷺ, que puso la piedra sobre un paño, hizo que todas las tribus lo levantaran juntas y luego la colocó con su propia mano.","context":"En los relatos biográficos el Profeta ﷺ tenía unos treinta y cinco años.","disputed":"Los relatos discrepan sobre su edad en la reconstrucción de la Kaaba; la cifra más conocida es de unos treinta y cinco años.","sources":[["La Biografía profética — Ibn Hishām","Relato de la reconstrucción de la Kaaba por Quraysh"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('secret_dawah','es','{"name":"La llamada privada","when":"Hacia 610 – 613","summary":"Los primeros años de la llamada, hecha en privado entre familiares y personas de confianza antes de hacerse pública.","bio":"El Profeta ﷺ llamó en privado a quienes confiaba; Jadīya, Abū Bakr, ʿAlī, Zayd ibn Ḥāritha y otros lo siguieron, y los musulmanes ocultaban su culto.","context":"Las biografías mencionan que la casa de al-Arqam ibn Abī al-Arqam fue uno de los lugares de reunión de los musulmanes.","disputed":"Se suele decir que la fase privada duró unos tres años; los relatos discrepan sobre su duración.","sources":[["La Biografía profética — Ibn Hishām","Relato del inicio de la llamada y de los primeros en abrazar el islam"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('persecution','es','{"name":"Persecución de los primeros musulmanes","when":"Desde hacia el 613","summary":"El daño sufrido por el Profeta ﷺ y por los musulmanes vulnerables después de que la llamada se hizo pública.","bio":"Muchos musulmanes vulnerables fueron torturados y dañados, entre ellos Bilāl ibn Rabāḥ; Abū Bakr compró a varios y los liberó, y el Profeta ﷺ mismo sufrió daños y burlas.","context":"Esta adversidad llevó a algunos musulmanes a emigrar a Abisinia.","sources":[["La Biografía profética — Ibn Hishām","Relato del daño que sufrieron los musulmanes"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('boycott','es','{"name":"El boicot en el valle de Abū Ṭālib","when":"Hacia 616 – 619 (años 7.º a 10.º de la misión)","summary":"El boicot de los Banū Hāshim y los Banū al-Muṭṭalib por los Quraysh, que quedaron confinados en el valle.","bio":"Los Quraysh acordaron boicotear a los Banū Hāshim y a los Banū al-Muṭṭalib en el comercio y el matrimonio; el Profeta ﷺ y quienes lo acompañaban se refugiaron un tiempo en el valle de Abū Ṭālib, hasta que se anuló el pacto.","context":"Fue seguido por el Año de la Tristeza.","disputed":"Los relatos discrepan sobre cuándo empezó y cuánto duró: la cifra más conocida es de unos tres años y algunos dicen menos.","sources":[["La Biografía profética — Ibn Hishām","Relato del documento del pacto y del asedio del valle"],["El Principio y el Fin — Ibn Kazīr","El asedio de los Banū Hāshim en el valle"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('taif_trip','es','{"name":"El viaje a Ṭāʾif","when":"Shawwāl, 10.º año de la misión – hacia el 619","summary":"El viaje del Profeta ﷺ a Ṭāʾif para llamar a su gente, tras la muerte de Abū Ṭālib y Jadīya.","bio":"Salió con Zayd ibn Ḥāritha y ofreció el islam a los jefes de Zaqīf, que lo rechazaron y lanzaron contra él a sus insensatos, que le arrojaron piedras; luego volvió a La Meca bajo la protección de al-Muṭʿim ibn ʿAdī.","context":"El Ṣaḥīḥ contiene el relato de ʿĀʾisha sobre el día más duro que vivió el Profeta ﷺ, en Ṭāʾif.","sources":[["Sahih al-Bujari","Libro del comienzo de la creación"],["La Biografía profética — Ibn Hishām","Relato de su viaje a Ṭāʾif"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('khaybar','es','{"name":"La campaña de Jaybar","when":"Muḥarram del año 7 H. – 628","summary":"La campaña de los musulmanes contra las fortalezas de los judíos de Jaybar, al norte de Medina, tras el tratado de al-Ḥudaybiya.","bio":"Al volver de al-Ḥudaybiya, el Profeta ﷺ marchó sobre Jaybar, asedió y tomó sus fortalezas, y dejó que su gente siguiera cultivando la tierra por la mitad de la cosecha.","context":"El Ṣaḥīḥ cuenta que el Profeta ﷺ entregó el estandarte a ʿAlī ibn Abī Ṭālib en esta campaña.","disputed":"Los relatos discrepan sobre el mes: el más conocido es Muḥarram del séptimo año; también se citan otros meses.","sources":[["Sahih al-Bujari","Libro de las campañas, capítulo: la campaña de Jaybar"],["La Biografía profética — Ibn Hishām","Relato de la campaña de Jaybar"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('muta','es','{"name":"La batalla de Muʾta","when":"Jumādā al-Ūlā del año 8 H. – 629","summary":"Una batalla entre los musulmanes y el ejército bizantino y sus aliados en el borde de al-Shām, en la que murieron mártires tres comandantes musulmanes.","bio":"El Profeta ﷺ envió un ejército bajo Zayd ibn Ḥāritha, luego Jaʿfar ibn Abī Ṭālib y luego ʿAbd Allāh ibn Rawāḥa; los tres murieron mártires, y Jālid ibn al-Walīd tomó el estandarte y devolvió al ejército.","context":"En el relato de al-Bujārī, el Profeta ﷺ llamó a Jālid una espada de las espadas de Dios en esta ocasión.","disputed":"Los relatos varían en las cifras de los dos ejércitos y en la descripción del resultado.","sources":[["Sahih al-Bujari","Libro de las campañas, capítulo: la campaña de Muʾta en tierras de al-Shām"],["La Biografía profética — Ibn Hishām","Relato de la campaña de Muʾta"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('hunayn','es','{"name":"La batalla de Ḥunayn","when":"Shawwāl del año 8 H. – 630","summary":"La batalla de los musulmanes contra Hawāzin y Zaqīf tras la conquista de La Meca.","bio":"Los musulmanes salieron con un gran ejército; el enemigo los sorprendió en el valle de Ḥunayn y sus filas flaquearon, pero el Profeta ﷺ y quienes estaban con él resistieron, los musulmanes se reagruparon y vencieron.","context":"El Corán alude a este día en la sura al-Tawba; después los musulmanes se dirigieron a Ṭāʾif.","sources":[["Sahih al-Bujari","Libro de las campañas, capítulo: la palabra de Dios «y el día de Ḥunayn»"],["El Noble Corán","Sura al-Tawba 9:25–26"],["La Biografía profética — Ibn Hishām","Relato de la campaña de Ḥunayn"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('tabuk','es','{"name":"La expedición a Tabūk","when":"Rajab del año 9 H. – 630","summary":"La marcha del Profeta ﷺ con un gran ejército hacia Tabūk, en el borde de al-Shām; no hubo combate.","bio":"El Profeta ﷺ salió en tiempo de dificultad y calor para enfrentar las concentraciones bizantinas de las que había oído; llegó a Tabūk, permaneció unos días y volvió sin combatir. Su ejército se llamó el Ejército de la Penuria.","context":"Tres Compañeros se quedaron atrás y más tarde fueron perdonados.","disputed":"Los relatos varían sobre cuánto tiempo permaneció en Tabūk.","sources":[["Sahih al-Bujari","Libro de las campañas, capítulo: la campaña de Tabūk"],["El Noble Corán","Sura al-Tawba 9:117–118"]]}'::jsonb,'draft',null,null) on conflict do nothing;
insert into entity_translations (entity_id,lang,fields,translation_status,translation_reviewed_by,translation_reviewed_at) values ('illness','es','{"name":"La última enfermedad del Profeta ﷺ","when":"Finales de Ṣafar – Rabīʿ al-Awwal del año 11 H. – 632","summary":"Los últimos días de enfermedad del Profeta ﷺ en la casa de ʿĀʾisha hasta su muerte.","bio":"Al agravarse su enfermedad pidió permiso a sus esposas para ser cuidado en la casa de ʿĀʾisha, y ellas aceptaron; ordenó a Abū Bakr dirigir la oración de la gente.","context":"La preparación del ejército de Usāma ibn Zayd precedió a su enfermedad.","disputed":"Los relatos discrepan sobre el inicio y la duración de la enfermedad: la cifra más conocida es de unos diez días y algunos dicen trece.","sources":[["Sahih al-Bujari","Libro de las campañas, capítulo: la enfermedad y muerte del Profeta ﷺ"],["Sahih al-Bujari","Libro de la llamada a la oración, capítulo: la gente de ciencia y mérito tiene más derecho a dirigir la oración"]]}'::jsonb,'draft',null,null) on conflict do nothing;
